package main
import ("fmt";"sort")
type Item struct{Name string; Size int}
func trial(n int, stable bool, revIter bool){
 items:=make([]Item,n)
 for i:=0;i<n;i++{items[i]=Item{fmt.Sprintf("f%02d",i),4096}}
 less:=func(i,j int)bool{return items[i].Size < items[j].Size}
 if stable { sort.SliceStable(items, less)} else { sort.Slice(items, less)}
 fmt.Printf("n=%d stable=%v ",n,stable)
 if revIter { for i:=n-1;i>=0;i--{fmt.Printf("%s ",items[i].Name)} } else { for _,it:=range items{fmt.Printf("%s ",it.Name)} }
 fmt.Println()
}
func main(){
 for _,n:=range []int{3,4,8,15,20,50,100}{
   trial(n,true,true); trial(n,false,true); trial(n,false,false)
 }
}
GO
cd /tmp/gotest && go run main.go"}

