type I struct{Name string; Size int}
func main(){
 for _,stable:=range []bool{true,false}{
  items:=[]I{}
  for i:=0;i<30;i++{sz:=4096; if i%2==1{sz=8192}; items=append(items,I{fmt.Sprintf("f%02d",i),sz})}
  less:=func(i,j int)bool{return items[i].Size<items[j].Size}
  if stable{sort.SliceStable(items,less)}else{sort.Slice(items,less)}
  fmt.Println("stable",stable)
  for k:=len(items)-1;k>=0;k--{fmt.Print(items[k].Name," ")}
  fmt.Println()
 }
}
GO
cd /tmp/gotest && go run main.go"}

