func orderedByUsage(items []Item, reverseSort bool) []Item {
	asc := sortedByUsageAsc(items)
	if reverseSort {
		return asc
	}
	// reverse
	for i, j := 0, len(asc)-1; i < j; i, j = i+1, j-1 {
		asc[i], asc[j] = asc[j], asc[i]
	}
	return asc
}

func formatSize(size int64, f *Flags) string {
	if f.NoPrefix {
		return fmt.Sprintf("%d", size)
	}
	if f.ShowInKiB {
		if f.UseSIPrefix {
			return fmt.Sprintf("%.1f kB", float64(size)/1000.0)
		}
		return fmt.Sprintf("%.1f KiB", float64(size)/1024.0)
	}
	if f.UseSIPrefix {
		units := []string{"B", "kB", "MB", "GB", "TB", "PB", "EB"}
		if size < 1000 {
			return fmt.Sprintf("%d B", size)
		}
		val := float64(size)
		idx := 0
		for val >= 1000 && idx < len(units)-1 {
			val /= 1000
			idx++
		}
		return fmt.Sprintf("%.1f %s", val, units[idx])
	}
	units := []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	if size < 1024 {
		return fmt.Sprintf("%d B", size)
	}
	val := float64(size)
	idx := 0
	for val >= 1024 && idx < len(units)-1 {
		val /= 1024
		idx++
	}
	// The loop above reduces once too far for cases like 1024 -> need standard algorithm:
	// Recompute properly:
	return humanizeBinary(size)
}

func humanizeBinary(size int64) string {
	units := []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"}
	if size < 1024 {
		return fmt.Sprintf("%d B", size)
	}
	val := float64(size)
	idx := 0
	for idx < len(units)-1 {
		if val < 1024 {
			break
		}
		val /= 1024
		idx++
	}
	return fmt.Sprintf("%.1f %s", val, units[idx])
}

func humanizeSI(size int64) string {
	units := []string{"B", "kB", "MB", "GB", "TB", "PB", "EB"}
	if size < 1000 {
		return fmt.Sprintf("%d B", size)
	}
	val := float64(size)
	idx := 0
	for idx < len(units)-1 {
		if val < 1000 {
			break
		}
		val /= 1000
		idx++
	}
	return fmt.Sprintf("%.1f %s", val, units[idx])
}

// split a formatted size into number and unit for coloring
func splitSize(s string) (string, string) {
	parts := strings.SplitN(s, " ", 2)
	if len(parts) == 2 {
		return parts[0], parts[1]
	}
	return s, ""
}

