	candidate := filepath.Join(home, ".config", "gdu", "gdu.yaml")
	if _, err := os.Stat(candidate); err == nil {
		return candidate
	}
	return filepath.Join(home, ".gdu.yaml")
}

// applyConfigFile reads config file (already resolved path) into flags.
// changed is set of cobra flag names explicitly set.
// Returns true if config applied successfully (no error).
func (f *Flags) applyConfigFile(changed map[string]bool) bool {
	if f.CfgFile == "" {
		// path resolution when flag empty
		f.CfgFile = defaultConfigPath()
	}
	data, err := os.ReadFile(f.CfgFile)
	if err != nil {
		logInfof("Error reading config file: %s", err.Error())
		return false
	}
	// typed struct for error detection
	var typed Flags
	// Pre-fill typed with defaults for style to detect? Unmarshal into empty; yaml errors are what we need.
	if err := yaml.Unmarshal(data, &typed); err != nil {
		logInfof("Error reading config file: %s", err.Error())
		return false
	}
	// presence map
	var raw map[string]interface{}
	_ = yaml.Unmarshal(data, &raw)
	if raw == nil {
		raw = map[string]interface{}{}
	}
	has := func(k string) bool { _, ok := raw[k]; return ok }
	// helper subs
	subHas := func(parent, k string) bool {
		if p, ok := raw[parent].(map[string]interface{}); ok {
			_, ok2 := p[k]
			return ok2
		}
		return false
	}
	// Style (no CLI)
	if has("style") {
		if subHas("style", "use-old-size-bar") { f.Style.UseOldSizeBar = typed.Style.UseOldSizeBar }
		// footer
		if ff, ok := raw["style"].(map[string]interface{}); ok {
			if _, ok := ff["footer"].(map[string]interface{}); ok {
				if subHas2(ff, "footer", "text-color") { f.Style.Footer.TextColor = typed.Style.Footer.TextColor }
				if subHas2(ff, "footer", "background-color") { f.Style.Footer.BackgroundColor = typed.Style.Footer.BackgroundColor }
				if subHas2(ff, "footer", "number-color") { f.Style.Footer.NumberColor = typed.Style.Footer.NumberColor }
			}
			if _, ok := ff["selected-row"].(map[string]interface{}); ok {
				if subHas2(ff, "selected-row", "text-color") { f.Style.SelectedRow.TextColor = typed.Style.SelectedRow.TextColor }
				if subHas2(ff, "selected-row", "background-color") { f.Style.SelectedRow.BackgroundColor = typed.Style.SelectedRow.BackgroundColor }
			}
			if _, ok := ff["result-row"].(map[string]interface{}); ok {
				if subHas2(ff, "result-row", "number-color") { f.Style.ResultRow.NumberColor = typed.Style.ResultRow.NumberColor }
				if subHas2(ff, "result-row", "directory-color") { f.Style.ResultRow.DirectoryColor = typed.Style.ResultRow.DirectoryColor }
			}
			if _, ok := ff["header"].(map[string]interface{}); ok {
				if subHas2(ff, "header", "text-color") { f.Style.Header.TextColor = typed.Style.Header.TextColor }
				if subHas2(ff, "header", "background-color") { f.Style.Header.BackgroundColor = typed.Style.Header.BackgroundColor }
				if subHas2(ff, "header", "hidden") { f.Style.Header.Hidden = typed.Style.Header.Hidden }
			}
			if _, ok := ff["progress-modal"].(map[string]interface{}); ok {
				if subHas2(ff, "progress-modal", "current-item-path-max-len") { f.Style.ProgressModal.CurrentItemNameMaxLen = typed.Style.ProgressModal.CurrentItemNameMaxLen }
			}
		}
	}
	if has("sorting") {
		if subHas("sorting", "by") { f.Sorting.By = typed.Sorting.By }
		if subHas("sorting", "order") { f.Sorting.Order = typed.Sorting.Order }
	}
	applyStr := func(yamlKey, flagName string, dst *string, src string) {
		if has(yamlKey) && !changed[flagName] { *dst = src }
	}
	applyBool := func(yamlKey, flagName string, dst *bool, src bool) {
		if has(yamlKey) && !changed[flagName] { *dst = src }
	}
	applyInt := func(yamlKey, flagName string, dst *int, src int) {
		if has(yamlKey) && !changed[flagName] { *dst = src }
	}
	applySlice := func(yamlKey, flagName string, dst *[]string, src []string) {
		if has(yamlKey) && !changed[flagName] {
			if src == nil { *dst = []string{} } else { *dst = src }
		}
	}
	applyStr("log-file", "log-file", &f.LogFile, typed.LogFile)
	applyStr("input-file", "input-file", &f.InputFile, typed.InputFile)
	applyStr("output-file", "output-file", &f.OutputFile, typed.OutputFile)
	applyStr("ignore-from-file", "ignore-from", &f.IgnoreFromFile, typed.IgnoreFromFile)
	applySlice("ignore-dirs", "ignore-dirs", &f.IgnoreDirs, typed.IgnoreDirs)
	applySlice("ignore-dir-patterns", "ignore-dirs-pattern", &f.IgnoreDirPatterns, typed.IgnoreDirPatterns)
	applySlice("type", "type", &f.TypeFilter, typed.TypeFilter)
	applySlice("exclude-type", "exclude-type", &f.ExcludeTypeFilter, typed.ExcludeTypeFilter)
	applyInt("max-cores", "max-cores", &f.MaxCores, typed.MaxCores)
	applyInt("top", "top", &f.Top, typed.Top)
	applyInt("depth", "depth", &f.Depth, typed.Depth)
	applyBool("sequential-scanning", "sequential", &f.SequentialScanning, typed.SequentialScanning)
	applyBool("show-apparent-size", "show-apparent-size", &f.ShowApparentSize, typed.ShowApparentSize)
	applyBool("show-relative-size", "show-relative-size", &f.ShowRelativeSize, typed.ShowRelativeSize)
	applyBool("show-annexed-size", "show-annexed-size", &f.ShowAnnexedSize, typed.ShowAnnexedSize)
	applyBool("show-item-count", "show-item-count", &f.ShowItemCount, typed.ShowItemCount)
	applyBool("show-mtime", "show-mtime", &f.ShowMTime, typed.ShowMTime)
	applyBool("no-color", "no-color", &f.NoColor, typed.NoColor)
	applyBool("mouse", "mouse", &f.Mouse, typed.Mouse)
	applyBool("non-interactive", "non-interactive", &f.NonInteractive, typed.NonInteractive)
	applyBool("no-progress", "no-progress", &f.NoProgress, typed.NoProgress)
	applyBool("no-unicode", "no-unicode", &f.NoUnicode, typed.NoUnicode)
	applyBool("no-cross", "no-cross", &f.NoCross, typed.NoCross)
	applyBool("no-hidden", "no-hidden", &f.NoHidden, typed.NoHidden)
	applyBool("no-delete", "no-delete", &f.NoDelete, typed.NoDelete)
	applyBool("no-spawn-shell", "no-spawn-shell", &f.NoSpawnShell, typed.NoSpawnShell)
	applyBool("follow-symlinks", "follow-symlinks", &f.FollowSymlinks, typed.FollowSymlinks)
	applyBool("profiling", "enable-profiling", &f.Profiling, typed.Profiling)
	applyBool("read-from-storage", "read-from-storage", &f.ReadFromStorage, typed.ReadFromStorage)
	applyStr("db", "db", &f.DbPath, typed.DbPath)
	applyBool("summarize", "summarize", &f.Summarize, typed.Summarize)
	applyBool("use-si-prefix", "si", &f.UseSIPrefix, typed.UseSIPrefix)
	applyBool("no-prefix", "no-prefix", &f.NoPrefix, typed.NoPrefix)
	applyBool("show-in-kib", "show-in-kib", &f.ShowInKiB, typed.ShowInKiB)
	applyBool("reverse-sort", "reverse-sort", &f.ReverseSort, typed.ReverseSort)
	// config-only
	if has("change-cwd") { f.ChangeCwd = typed.ChangeCwd }
	if has("delete-in-background") { f.DeleteInBackground = typed.DeleteInBackground }
	if has("delete-in-parallel") { f.DeleteInParallel = typed.DeleteInParallel }
	applyStr("since", "since", &f.Since, typed.Since)
	applyStr("until", "until", &f.Until, typed.Until)
	applyStr("max-age", "max-age", &f.MaxAge, typed.MaxAge)
	applyStr("min-age", "min-age", &f.MinAge, typed.MinAge)
	applyBool("archive-browsing", "archive-browsing", &f.ArchiveBrowsing, typed.ArchiveBrowsing)
	applyBool("collapse-path", "collapse-path", &f.CollapsePath, typed.CollapsePath)
	return true
}

func subHas2(parent map[string]interface{}, key, sub string) bool {
	if p, ok := parent[key].(map[string]interface{}); ok {
		_, ok2 := p[sub]
		return ok2
	}
	return false
}

func (f *Flags) writeConfig() error {
	data, err := yaml.Marshal(f)
	if err != nil {
		return fmt.Errorf("error writing config file %s: %w", f.CfgFile, err)
	}
	// write with 0600 truncating
	file, err := os.OpenFile(f.CfgFile, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
	if err != nil {
		return fmt.Errorf("error writing config file %s: %w", f.CfgFile, err)
	}
	defer file.Close()
	if _, err := file.Write(data); err != nil {
		return fmt.Errorf("error writing config file %s: %w", f.CfgFile, err)
	}
	return nil
}

var _ = strings.TrimSpace
EOF
"}

