{"command":"cat > log.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"strconv"
	"time"
)

var logOut *os.File

func openLogFile(path string) error {
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
	if err != nil {
		return err
	}
	if logOut != nil && logOut != os.Stderr {
		// do not close /dev/null repeatedly? closing is fine
		logOut.Close()
	}
	logOut = f
	return nil
}

func logInfof(format string, args ...interface{}) {
	if logOut == nil {
		return
	}
	msg := fmt.Sprintf(format, args...)
	ts := time.Now().Format("2006-01-02T15:04:05Z07:00")
	// logrus text formatter quotes msg
	line := fmt.Sprintf("time=%s level=info msg=%s\n", strconv.Quote(ts), strconv.Quote(msg))
	_, _ = logOut.WriteString(line)
}
