{"command":"cat > analyzer.go <<'EOF'
package main

import (
	"archive/zip"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"syscall"
)

type Analyzer struct {
	Flags          *Flags
	IgnoreDirsAbs  map[string]bool
	Patterns       []*regexp.Regexp
	PatternStrs    []string
	TimeFilter     *TimeFilter
	RootDev        uint64
	HasRootDev     bool
	Sequential     bool
	// for progress interface: counts
	OnItem func()
	StoredMode bool // used by stored analyzers to adjust handling? scanning itself same
}

func devOf(info os.FileInfo) uint64 {
	if st, ok := info.Sys().(*syscall.Stat_t); ok {
		return uint64(st.Dev)
	}
	return 0
}
func blocksUsage(info os.FileInfo) int64 {
	if st, ok := info.Sys().(*syscall.Stat_t); ok {
		return st.Blocks * 512
	}
	return 0
}
func inodeInfo(info os.FileInfo) (uint64, uint64) {
	if st, ok := info.Sys().(*syscall.Stat_t); ok {
		return st.Ino, uint64(st.Nlink)
	}
	return 0, 1
}

func (a *Analyzer) shouldIgnoreDir(absPath string, dirItem *Dir, name string) bool {
	if a.IgnoreDirsAbs[absPath] {
		logInfof("Directory %s ignored", absPath)
		return true
	}
	if len(a.Patterns) > 0 && a.matchPattern(absPath, dirItem, name) {
		logInfof("Directory %s ignored", absPath)
		return true
	}
	return false
}

func (a *Analyzer) matchPattern(absPath string, dirItem *Dir, name string) bool {
	// gather candidates
	cwd, _ := os.Getwd()
	// candidate strings for prefix matching
	candidatesPrefix := []string{absPath}
	if cwd != "" {
		if rel, err := filepath.Rel(cwd, absPath); err == nil {
			candidatesPrefix = append(candidatesPrefix, rel, "/"+rel)
		}
	}
	// virtual path (relative to root scanning path - approximate using dirItem parent chain if available)
	// We'll also compute later in caller? Use absPath suffix handling etc.
	for _, pat := range a.Patterns {
		for _, cand := range candidatesPrefix {
			if loc := pat.FindStringIndex(cand); loc != nil && loc[0] == 0 {
				return true
			}
		}
		// suffix handling for patterns containing '/'
		// original pattern suffix
		if locs := pat.FindAllStringIndex(absPath, -1); locs != nil {
			for _, loc := range locs {
				if loc[1] == len(absPath) {
					// but require that pattern starts with '/' or contains '/' (?), and that the match is not just a plain name (?), handled by caller for plain?
					// This already would be true for plain 'alpha$' etc. Restrict: if pattern string contains '/'
					// We need access to original string; handled below via PatternStrs parallel loop
					_ = loc
				}
			}
		}
	}
	// suffix + transformed checks using pattern strings
	for idx, patStr := range a.PatternStrs {
		pat := a.Patterns[idx]
		_ = pat
		if strings.Contains(patStr, "/") {
			stripped := strings.TrimPrefix(patStr, "/")
			if re, err := regexp.Compile(stripped); err == nil {
				if locs := re.FindAllStringIndex(absPath, -1); locs != nil {
					for _, loc := range locs {
						if loc[1] == len(absPath) {
							return true
						}
					}
				}
			}
			// raw pattern suffix
			if locs := pat.FindAllStringIndex(absPath, -1); locs != nil {
				for _, loc := range locs {
					if loc[1] == len(absPath) {
						return true
					}
				}
			}
		}
		// transformed absolute candidate for simple (path-like) patterns
		isSimple := true
		if strings.ContainsAny(patStr, `^$*+?()|[]\`) {
			isSimple = false
		}
		if isSimple && !strings.HasPrefix(patStr, "/") {
			transformed := patStr
			if cwd != "" {
				transformed = filepath.Join(cwd, patStr)
			}
			if re, err := regexp.Compile("^" + regexp.QuoteMeta(transformed)); err == nil {
				// apply as regex (quoted) prefix to candidates that correspond to our virtual candidates
				// candidates: absPath and virtual "/"+base name ?
				// virtual: we can reconstruct from dirItem if parent chain available
				cands := []string{absPath}
				if dirItem != nil {
					cands = append(cands, dirItem.GetPath())
					// root-base candidate: first component of scanpath? use GetPath first element
					// Build "/"+rootbase+"/"+rel
					// root base is first path element of GetPath after root? GetPath gives abs for root children, too same.
				}
				for _, cand := range cands {
					if re.MatchString(cand) {
						return true
					}
				}
			}
			// also transformed == absPath check (already via re)
		}
		// relative to cwd prefix already handled
	}
	return false
}

func (a *Analyzer) Analyze(path string) (*Dir, error) {
	absPath, err := filepath.Abs(path)
	if err != nil {
		absPath = path
	}
	info, err := os.Stat(absPath)
	if err != nil {
		return nil, err
	}
	logInfof("Analyzing path: %s", absPath)
	a.RootDev = devOf(info)
	a.HasRootDev = true
	root := &Dir{
		Name:      absPath,
		Size:      4096,
		Usage:     4096,
		OwnSize:   4096,
		BaseMtime: info.ModTime(),
		Mtime:     info.ModTime(),
		FsPath:    absPath,
		Flag:      ' ',
	}
	// if profiling etc ignored
	a.processDir(root, absPath)
	root.updateStats()
	return root, nil
}

func (a *Analyzer) processDir(dir *Dir, fsPath string) {
	entries, err := os.ReadDir(fsPath)
	if err != nil {
		logInfof("%s", err.Error())
		// Determine: if dir is not root? flag !
		dir.Flag = '!'
		dir.FlagSet = false
		// keep flag as ! stored in Flag field; GetFlag returns it
		return
	}
	if len(entries) == 0 {
		dir.emptyMarked = true
		if dir.Flag == ' ' || dir.Flag == 0 {
			dir.Flag = 'e'
		}
	}
	// os.ReadDir sorts by filename
	if a.Sequential {
		for _, e := range entries {
			a.processEntry(dir, fsPath, e)
		}
	} else {
		// files first, then dirs (deterministic dirs in entry order)
		var dirs []os.DirEntry
		for _, e := range entries {
			if e.IsDir() {
				dirs = append(dirs, e)
			} else {
				a.processEntry(dir, fsPath, e)
			}
		}
		for _, e := range dirs {
			a.processEntry(dir, fsPath, e)
		}
	}
}

func (a *Analyzer) processEntry(parent *Dir, parentPath string, e os.DirEntry) {
	name := e.Name()
	childPath := filepath.Join(parentPath, name)
	if a.OnItem != nil {
		a.OnItem()
	}
	if e.IsDir() {
		// subdir
		if a.Flags.NoHidden && strings.HasPrefix(name, ".") {
			return
		}
		info, err := e.Info()
		if err != nil {
			logInfof("%s", err.Error())
			return
		}
		// ignore checks need a Dir placeholder for pattern matching (path)
		placeholder := &Dir{Name: name, Parent: parent}
		if a.shouldIgnoreDir(childPath, placeholder, name) {
			return
		}
		if a.Flags.NoCross && a.HasRootDev {
			if devOf(info) != a.RootDev {
				return
			}
		}
		sub := &Dir{
			Name:      name,
			Parent:    parent,
			Size:      4096,
			Usage:     4096,
			OwnSize:   4096,
			BaseMtime: info.ModTime(),
			Mtime:     info.ModTime(),
			FsPath:    childPath,
			Flag:      ' ',
		}
		parent.Files = append(parent.Files, sub)
		a.processDir(sub, childPath)
		return
	}
	// file / symlink etc
	info, err := e.Info()
	if err != nil {
		logInfof("%s", err.Error())
		return
	}
	// symlink handling etc may produce a Dir for archive
	file, archiveDir := a.createFileOrArchive(parent, childPath, name, info, e)
	if archiveDir != nil {
		parent.Files = append(parent.Files, archiveDir)
		return
	}
	if file == nil {
		return
	}
	// filters
	if !a.passTypeFilter(name) {
		return
	}
	if a.TimeFilter != nil && !a.TimeFilter.include(file.Mtime) {
		return
	}
	file.Parent = parent
	parent.Files = append(parent.Files, file)
}

func (a *Analyzer) passTypeFilter(name string) bool {
	if len(a.Flags.TypeFilter) > 0 {
		ext := fileExtNormalized(name)
		for _, t := range normalizedTypes(a.Flags.TypeFilter) {
			if ext == t {
				return true
			}
		}
		return false
	}
	if len(a.Flags.ExcludeTypeFilter) > 0 {
		ext := fileExtNormalized(name)
		for _, t := range normalizedTypes(a.Flags.ExcludeTypeFilter) {
			if ext == t {
				return false
			}
		}
		return true
	}
	return true
}

func fileExtNormalized(name string) string {
	ext := filepath.Ext(name) // includes dot or ""
	return strings.ToLower(ext)
}
func normalizedTypes(list []string) []string {
	out := make([]string, 0, len(list))
	for _, t := range list {
		lt := strings.ToLower(t)
		if !strings.HasPrefix(lt, ".") {
			lt = "." + lt
		}
		out = append(out, lt)
	}
	return out
}

func (a *Analyzer) createFileOrArchive(parent *Dir, path string, name string, info os.FileInfo, e os.DirEntry) (*File, *Dir) {
	origInfo := info
	isSymlink := info.Mode()&os.ModeSymlink != 0
	effectiveInfo := info
	annexSize := int64(-1)
	if isSymlink && a.Flags.FollowSymlinks {
		// try to follow
		targetInfo, err := os.Stat(path)
		if err != nil {
			// annex?
			if a.Flags.ShowAnnexedSize {
				if linkDest, lerr := os.Readlink(path); lerr == nil {
					// check contains .git/annex/objects/
					if strings.Contains(linkDest, ".git/annex/objects/") {
						sz := parseAnnexSize(linkDest)
						f := &File{Name: name, Size: sz, Usage: 0, Mtime: info.ModTime(), NotReg: true}
						// type/time filters applied by caller
						return f, nil
					}
				}
			}
			// log error as original: they seem to log lstat of target; use Stat error string but transform?
			// Observed: "lstat /nonexistent: no such file or directory"
			// Try to replicate: if readlink succeeds, log lstat of target destination (as given / resolved)
			if linkDest, lerr := os.Readlink(path); lerr == nil {
				dest := linkDest
				if !filepath.IsAbs(dest) {
					dest = filepath.Join(filepath.Dir(path), dest)
				}
				// emulate error from Lstat(dest)
				if _, lerr2 := os.Lstat(dest); lerr2 != nil {
					logInfof("%s", lerr2.Error())
				} else {
					logInfof("%s", err.Error())
				}
			} else {
				logInfof("%s", err.Error())
			}
			return nil, nil
		}
		if targetInfo.IsDir() {
			// keep original symlink file
		} else {
			effectiveInfo = targetInfo
		}
	}
	_ = origInfo
	_ = annexSize
	// Archive check: only for regular files (after follow? Original file name ext)
	if a.Flags.ArchiveBrowsing && !effectiveInfo.IsDir() {
		lower := strings.ToLower(name)
		if strings.HasSuffix(lower, ".zip") || strings.HasSuffix(lower, ".jar") {
			// only if original is a regular file (or followed regular)
			// Try open zip using the filesystem path
			adir, err := a.processArchive(parent, path, name, effectiveInfo)
			if err != nil {
				logInfof("Failed to process zip file %s: %s", path, err.Error())
			} else {
				// type/time filters? Archives are dirs - they are not filtered by type/time in original? Files inside?
				// It was added as dir, bypass type/time for the archive container itself.
				return nil, adir
			}
		}
	}
	f := makeFileFromInfo(name, effectiveInfo, isSymlink && effectiveInfo == origInfo)
	return f, nil
}

func makeFileFromInfo(name string, info os.FileInfo, isOrigSymlink bool) *File {
	f := &File{
		Name:  name,
		Size:  info.Size(),
		Usage: blocksUsage(info),
		Mtime: info.ModTime(),
	}
	mode := info.Mode()
	if mode&os.ModeSymlink != 0 || mode&os.ModeSocket != 0 {
		f.NotReg = true
	}
	if info.Mode().IsRegular() {
		ino, nlink := inodeInfo(info)
		if nlink > 1 {
			f.Mli = int64(ino)
			f.Hlnkc = true
		}
	}
	if isOrigSymlink {
		// symlink file itself: mode is symlink, already NotReg
		f.NotReg = true
		// size/usage already from lstat
	}
	return f
}

func parseAnnexSize(linkDest string) int64 {
	// find "-s" followed by digits
	idx := strings.Index(linkDest, "-s")
	if idx < 0 {
		return 0
	}
	rest := linkDest[idx+2:]
	digits := ""
	for _, ch := range rest {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		} else {
			break
		}
	}
	if digits == "" {
		return 0
	}
	v, err := strconv.ParseInt(digits, 10, 64)
	if err != nil {
		return 0
	}
	return v
}

func (a *Analyzer) processArchive(parent *Dir, path string, name string, info os.FileInfo) (*Dir, error) {
	r, err := zip.OpenReader(path)
	if err != nil {
		return nil, err
	}
	defer r.Close()
	adir := &Dir{
		Name:      name,
		Parent:    parent,
		Size:      4096,
		Usage:     4096,
		OwnSize:   4096,
		BaseMtime: info.ModTime(),
		Mtime:     info.ModTime(),
		FsPath:    path,
		Flag:      ' ',
		IsArchive: true,
	}
	// Build tree
	dirsMap := map[string]*Dir{"": adir}
	getDir := func(dirPath string) *Dir {
		if dirPath == "" || dirPath == "." {
			return adir
		}
		if d, ok := dirsMap[dirPath]; ok {
			return d
		}
		// create intermediate
		parentPath := filepath.Dir(dirPath)
		if parentPath == "." {
			parentPath = ""
		}
		p := getDir(parentPath)
		nd := &Dir{
			Name:      filepath.Base(dirPath),
			Parent:    p,
			Size:      4096,
			Usage:     4096,
			OwnSize:   4096,
			BaseMtime: info.ModTime(),
			Mtime:     info.ModTime(),
			FsPath:    filepath.Join(path, dirPath),
			Flag:      ' ',
		}
		p.Files = append(p.Files, nd)
		dirsMap[dirPath] = nd
		return nd
	}
	for _, zf := range r.File {
		zname := zf.Name
		if strings.HasSuffix(zname, "/") {
			continue
		}
		// filters: type and time (based on zip file)
		// Zip file header time
		mtime := zf.Modified
		// file item
		base := filepath.Base(zname)
		if !a.passTypeFilter(base) {
			continue
		}
		if a.TimeFilter != nil && !a.TimeFilter.include(mtime) {
			continue
		}
		dirPart := filepath.Dir(zname)
		if dirPart == "." {
			dirPart = ""
		}
		d := getDir(dirPart)
		sz := int64(zf.UncompressedSize64)
		f := &File{
			Name:   base,
			Parent: d,
			Size:   sz,
			Usage:  sz,
			Mtime:  mtime,
		}
		d.Files = append(d.Files, f)
	}
	adir.updateStatsArchive()
	return adir, nil
}

func (d *Dir) updateStatsArchive() {
	// similar to updateStats but files have own sizes, no hardlink dedup
	d.updateStats()
}

// sorting import needed if unused
var _ = sort.StringSlice{}
EOF
"}

