func parseAnnexSize(linkDest string) int64 {
	// find "-s" followed by digits
	idx := strings.Index(linkDest, "-s")
	if idx < 0 {
		return 0
	}
	rest := linkDest[idx+2:]
	digits := ""
	for _, ch := range rest {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		} else {
			break
		}
	}
	if digits == "" {
		return 0
	}
	v, err := strconv.ParseInt(digits, 10, 64)
	if err != nil {
		return 0
	}
	return v
