{"command":"cat > storage.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// SQLite storage handling

const sqliteSchema = `
CREATE TABLE IF NOT EXISTS items (
		id          INTEGER PRIMARY KEY,
		parent_id   INTEGER REFERENCES items(id),
		name        TEXT NOT NULL,
		is_dir      INTEGER NOT NULL,
		size        INTEGER NOT NULL,
		usage       INTEGER NOT NULL,
		mtime       INTEGER NOT NULL,
		item_count  INTEGER NOT NULL DEFAULT 1,
		mli         INTEGER NOT NULL DEFAULT 0,
		flag        TEXT NOT NULL DEFAULT ' '
	);
CREATE INDEX IF NOT EXISTS idx_items_parent_id ON items(parent_id);
CREATE INDEX IF NOT EXISTS idx_items_mli ON items(mli) WHERE mli != 0;
CREATE TABLE IF NOT EXISTS metadata (
		key   TEXT PRIMARY KEY,
		value TEXT
	);
`

// createSQLiteAnalyzer opens (and for non-read, removes old) DB.
// Returned db is ready with schema.
func createSQLiteAnalyzer(f *Flags) (*sqliteDB, error) {
	path := f.DbPath
	if !f.ReadFromStorage {
		// remove existing file if possible
		_ = os.Remove(path)
	}
	db, err := openSQLite(path)
	if err != nil {
		return nil, fmt.Errorf("creating sqlite analyzer: %w", err)
	}
	// validate / create schema. For read mode on a corrupt file, this will fail with NOTADB.
	// For non-read mode, file was removed so schema creation succeeds.
	// Modernc driver presumably executes something on open that validates header when querying.
	if f.ReadFromStorage {
		// force a read to detect not a database
		if err := db.exec("SELECT name FROM sqlite_master LIMIT 1"); err != nil {
			db.close()
			return nil, fmt.Errorf("creating sqlite analyzer: %w", err)
		}
	}
	if err := db.exec(sqliteSchema); err != nil {
		// If corrupt and reading, this is the creation error
		db.close()
		return nil, fmt.Errorf("creating sqlite analyzer: %w", err)
	}
	return db, nil
}

// store tree to sqlite, sequential DFS order, clear existing rows first
func storeToSQLite(db *sqliteDB, root *Dir) error {
	if err := db.exec("DELETE FROM items; DELETE FROM metadata;"); err != nil {
		return err
	}
	// insert metadata
	// Use prepared statements
	ins, err := db.prepare("INSERT INTO items(id, parent_id, name, is_dir, size, usage, mtime, item_count, mli, flag) VALUES(?,?,?,?,?,?,?,?,?,?)")
	if err != nil { return err }
	defer ins.finalize()
	meta, err := db.prepare("INSERT OR REPLACE INTO metadata(key, value) VALUES(?,?)")
	if err != nil { return err }
	defer meta.finalize()

	// We must have sizes computed. Root and dirs have totals.
	nextID := int64(1)
	seen := make(map[int64]bool)
	type entry struct {
		item Item
		parentID int64
		isRoot bool
	}
	// We'll do recursive insertion sequential DFS (entry order stored from sequential-like sorting?)
	// For storage, original uses a sequential traversal in alphabetical/entry order.
	// Our root.Files order may be parallel order. To approximate storage order, we will traverse in an order:
	// At each dir, iterate children sorted by name ascending (files and dirs interleaved).
	// That matches sequential stored order.
	var insertDir func(d *Dir, parentID int64, name string) (int64, error)
	insertDir = func(d *Dir, parentID int64, name string) (int64, error) {
		id := nextID; nextID++
		ins.reset()
		ins.bindInt(1, id)
		if parentID == 0 {
			ins.bindNull(2)
		} else {
			ins.bindInt(2, parentID)
		}
		ins.bindText(3, name)
		ins.bindInt(4, 1)
		ins.bindInt(5, d.Size)
		ins.bindInt(6, d.Usage)
		ins.bindInt(7, d.Mtime.Unix())
		ins.bindInt(8, int64(d.GetItemCount()))
		ins.bindInt(9, 0)
		flag := d.GetFlag()
		ins.bindText(10, string([]byte{flag}))
		if _, err := ins.step(); err != nil { return 0, err }
		// children sorted by name
		children := make([]Item, len(d.Files))
		copy(children, d.Files)
		// sort by name ascending
		for i:=0;i<len(children);i++ {
			for j:=i+1;j<len(children);j++ {
				if children[j].GetName() < children[i].GetName() {
					children[i], children[j] = children[j], children[i]
				}
			}
		}
		for _, ch := range children {
			if sub, ok := ch.(*Dir); ok {
				if _, err := insertDir(sub, id, sub.Name); err != nil { return 0, err }
			} else if file, ok := ch.(*File); ok {
				fid := nextID; nextID++
				ins.reset()
				ins.bindInt(1, fid)
				ins.bindInt(2, id)
				ins.bindText(3, file.Name)
				ins.bindInt(4, 0)
				size := file.Size
				usage := file.Usage
				fl := byte(' ')
				if file.Hlnkc && file.Mli != 0 {
					if seen[file.Mli] {
						size = 0; usage = 0; fl = 'H'
					} else {
						seen[file.Mli] = true
						// first occurrence flag remains space unless NotReg
						if file.NotReg { fl = '@' } else { fl = ' ' }
					}
				} else if file.NotReg {
					fl = '@'
				}
				ins.bindInt(5, size)
				ins.bindInt(6, usage)
				ins.bindInt(7, file.Mtime.Unix())
				ins.bindInt(8, 1)
				if file.Hlnkc {
					ins.bindInt(9, file.Mli)
				} else {
					ins.bindInt(9, 0)
				}
				ins.bindText(10, string([]byte{fl}))
				if _, err := ins.step(); err != nil { return 0, err }
			}
		}
		return id, nil
	}
	rootName := filepath.Base(root.GetName())
	if root.GetName() == "/" {
		rootName = "/"
	}
	// Root name in DB is base; for a file-root, also base
	if _, err := insertDir(root, 0, rootName); err != nil {
		return err
	}
	meta.bindText(1, "top_dir_path")
	meta.bindText(2, root.GetName())
	if _, err := meta.step(); err != nil { return err }
	return nil
}

func loadFromSQLite(db *sqliteDB) (*Dir, error) {
	// Find root (parent_id IS NULL). If none, error to signal fallback
	q, err := db.prepare("SELECT id, name, is_dir, size, usage, mtime, item_count, mli, flag FROM items ORDER BY id")
	if err != nil { return nil, err }
	defer q.finalize()
