)

// SQLite storage handling

const sqliteSchema = `
CREATE TABLE IF NOT EXISTS items (
		id          INTEGER PRIMARY KEY,
		parent_id   INTEGER REFERENCES items(id),
		name        TEXT NOT NULL,
		is_dir      INTEGER NOT NULL,
		size        INTEGER NOT NULL,
		usage       INTEGER NOT NULL,
		mtime       INTEGER NOT NULL,
		item_count  INTEGER NOT NULL DEFAULT 1,
		mli         INTEGER NOT NULL DEFAULT 0,
		flag        TEXT NOT NULL DEFAULT ' '
	);
CREATE INDEX IF NOT EXISTS idx_items_parent_id ON items(parent_id);
CREATE INDEX IF NOT EXISTS idx_items_mli ON items(mli) WHERE mli != 0;
CREATE TABLE IF NOT EXISTS metadata (
		key   TEXT PRIMARY KEY,
		value TEXT
	);
`

// createSQLiteAnalyzer opens (and for non-read, removes old) DB.
// Returned db is ready with schema.
func createSQLiteAnalyzer(f *Flags) (*sqliteDB, error) {
	path := f.DbPath
	if !f.ReadFromStorage {
		// remove existing file if possible
		_ = os.Remove(path)
	}
	db, err := openSQLite(path)
	if err != nil {
		return nil, fmt.Errorf("creating sqlite analyzer: %w", err)
	}
	// validate / create schema. For read mode on a corrupt file, this will fail with NOTADB.
	// For non-read mode, file was removed so schema creation succeeds.
	// Modernc driver presumably executes something on open that validates header when querying.
	if f.ReadFromStorage {
		// force a read to detect not a database
		if err := db.exec("SELECT name FROM sqlite_master LIMIT 1"); err != nil {
			db.close()
			return nil, fmt.Errorf("creating sqlite analyzer: %w", err)
		}
	}
	if err := db.exec(sqliteSchema); err != nil {
		// If corrupt and reading, this is the creation error
		db.close()
		return nil, fmt.Errorf("creating sqlite analyzer: %w", err)
	}
	return db, nil
}

// store tree to sqlite, sequential DFS order, clear existing rows first
func storeToSQLite(db *sqliteDB, root *Dir) error {
	if err := db.exec("DELETE FROM items; DELETE FROM metadata;"); err != nil {
		return err
	}
	// insert metadata
	// Use prepared statements
	ins, err := db.prepare("INSERT INTO items(id, parent_id, name, is_dir, size, usage, mtime, item_count, mli, flag) VALUES(?,?,?,?,?,?,?,?,?,?)")
	if err != nil { return err }
	defer ins.finalize()
	meta, err := db.prepare("INSERT OR REPLACE INTO metadata(key, value) VALUES(?,?)")
	if err != nil { return err }
	defer meta.finalize()

	// We must have sizes computed. Root and dirs have totals.
	nextID := int64(1)
	seen := make(map[int64]bool)
	type entry struct {
		item Item
		parentID int64
		isRoot bool
	}
	// We'll do recursive insertion sequential DFS (entry order stored from sequential-like sorting?)
	// For storage, original uses a sequential traversal in alphabetical/entry order.
	// Our root.Files order may be parallel order. To approximate storage order, we will traverse in an order:
	// At each dir, iterate children sorted by name ascending (files and dirs interleaved).
	// That matches sequential stored order.
	var insertDir func(d *Dir, parentID int64, name string) (int64, error)
	insertDir = func(d *Dir, parentID int64, name string) (int64, error) {
		id := nextID; nextID++
		ins.reset()
		ins.bindInt(1, id)
		if parentID == 0 {
			ins.bindNull(2)
		} else {
			ins.bindInt(2, parentID)
		}
		ins.bindText(3, name)
		ins.bindInt(4, 1)
		ins.bindInt(5, d.Size)
		ins.bindInt(6, d.Usage)
		ins.bindInt(7, d.Mtime.Unix())
		ins.bindInt(8, int64(d.GetItemCount()))
		ins.bindInt(9, 0)
		flag := d.GetFlag()
		ins.bindText(10, string([]byte{flag}))
		if _, err := ins.step(); err != nil { return 0, err }
		// children sorted by name
		children := make([]Item, len(d.Files))
		copy(children, d.Files)
		// sort by name ascending
		for i:=0;i<len(children);i++ {
			for j:=i+1;j<len(children);j++ {
				if children[j].GetName() < children[i].GetName() {
					children[i], children[j] = children[j], children[i]
				}
			}
		}
		for _, ch := range children {
			if sub, ok := ch.(*Dir); ok {
				if _, err := insertDir(sub, id, sub.Name); err != nil { return 0, err }
			} else if file, ok := ch.(*File); ok {
				fid := nextID; nextID++
				ins.reset()
				ins.bindInt(1, fid)
				ins.bindInt(2, id)
				ins.bindText(3, file.Name)
				ins.bindInt(4, 0)
				size := file.Size
				usage := file.Usage
				fl := byte(' ')
				if file.Hlnkc && file.Mli != 0 {
					if seen[file.Mli] {
						size = 0; usage = 0; fl = 'H'
					} else {
						seen[file.Mli] = true
						// first occurrence flag remains space unless NotReg
						if file.NotReg { fl = '@' } else { fl = ' ' }
					}
				} else if file.NotReg {
					fl = '@'
				}
				ins.bindInt(5, size)
				ins.bindInt(6, usage)
				ins.bindInt(7, file.Mtime.Unix())
				ins.bindInt(8, 1)
				if file.Hlnkc {
					ins.bindInt(9, file.Mli)
				} else {
					ins.bindInt(9, 0)
				}
				ins.bindText(10, string([]byte{fl}))
				if _, err := ins.step(); err != nil { return 0, err }
			}
		}
		return id, nil
	}
	rootName := filepath.Base(root.GetName())
	if root.GetName() == "/" {
		rootName = "/"
	}
	// Root name in DB is base; for a file-root, also base
	if _, err := insertDir(root, 0, rootName); err != nil {
		return err
	}
	meta.bindText(1, "top_dir_path")
	meta.bindText(2, root.GetName())
	if _, err := meta.step(); err != nil { return err }
	return nil
}

func loadFromSQLite(db *sqliteDB) (*Dir, error) {
	// Find root (parent_id IS NULL). If none, error to signal fallback
	q, err := db.prepare("SELECT id, name, is_dir, size, usage, mtime, item_count, mli, flag FROM items ORDER BY id")
	if err != nil { return nil, err }
	defer q.finalize()
	type row struct { id, parent int64; hasParent bool; name string; isDir bool; size, usage, mtime, count, mli int64; flag string }
	// Need parent_id: adjust query
	// We'll re-prepare with parent column
	q.finalize()
	q2, err := db.prepare("SELECT id, parent_id, name, is_dir, size, usage, mtime, item_count, mli, flag FROM items ORDER BY id")
	if err != nil { return nil, err }
	defer q2.finalize()
	nodes := make(map[int64]Item)
	var root *Dir
	hasRoot := false
	for {
		has, err := q2.step()
		if err != nil { return nil, err }
		if !has { break }
		id := q2.colInt(0)
		parentNull := q2.colIsNull(1)
		var parentID int64
		if !parentNull { parentID = q2.colInt(1) }
		name := q2.colText(2)
		isDir := q2.colInt(3) != 0
		size := q2.colInt(4); usage := q2.colInt(5); mt := q2.colInt(6); cnt := q2.colInt(7); mli := q2.colInt(8); flagStr := q2.colText(9)
		var flagByte byte = ' '
		if len(flagStr) > 0 { flagByte = flagStr[0] }
		if isDir {
			d := &Dir{Name: name, Size: size, Usage: usage, OwnSize: 4096, BaseMtime: time.Unix(mt,0), Mtime: time.Unix(mt,0), ItemCount: int(cnt), Flag: flagByte, FlagSet: true}
			// Root special: Name will be overwritten from metadata later
			nodes[id] = d
			if parentNull {
				root = d; hasRoot = true
			} else {
				if p, ok := nodes[parentID].(*Dir); ok {
					d.Parent = p; p.Files = append(p.Files, d)
				}
			}
		} else {
			file := &File{Name: name, Size: size, Usage: usage, Mtime: time.Unix(mt,0), Mli: mli, Flag: flagByte, FlagSet: true}
			if mli != 0 { file.Hlnkc = true } // hlnkc approximation; flag stored handles display, totals already stored
			// NotReg derived from flag '@' for update stats? But stored totals for dirs are already in DB, so child files flags preserved.
			// For recompute after load we should NOT recompute dir totals; keep stored size/usage.
			// Parent linkage
			if p, ok := nodes[parentID].(*Dir); ok {
				file.Parent = p; p.Files = append(p.Files, file)
			}
			nodes[id] = file
		}
	}
	if !hasRoot {
		return nil, fmt.Errorf("no root found")
	}
	// metadata for top path
	mq, err := db.prepare("SELECT value FROM metadata WHERE key='top_dir_path'")
	if err == nil {
		defer mq.finalize()
		if has, _ := mq.step(); has {
			top := mq.colText(0)
			if top != "" {
				root.Name = top
			}
		}
	}
	// For files loaded from SQLite, set NotReg if flag '@' to help other logic (printing uses FlagSet)
	for _, n := range nodes {
		if f, ok := n.(*File); ok && f.Flag == '@' { f.NotReg = true }
	}
	return root, nil
}

// ----- Badger-like storage -----
// We store our tree as JSON-like inside a directory. Format is our own, stored in file storage.json.

type badgerStorage struct {
	Path string // directory
	Data *badgerData
}
type badgerData struct {
	Dirs map[string]*badgerDirRecord `json:"dirs"`
}
type badgerDirRecord struct {
	Path string                   `json:"path"`
	Dir  *badgerItem              `json:"dir"`
	Children []*badgerItem        `json:"children"`
	Top string                   `json:"top"`
}
type badgerItem struct {
	Name string `json:"name"`
	IsDir bool  `json:"is_dir"`
	Size int64  `json:"size"`
	Usage int64 `json:"usage"`
	Mtime int64  `json:"mtime"`
	Count int    `json:"count"`
	Mli int64   `json:"mli"`
	Hlnkc bool  `json:"hlnkc"`
	NotReg bool `json:"notreg"`
	Flag byte   `json:"flag"`
	IsArchive bool `json:"is_archive"`
	ChildPath string `json:"child_path,omitempty"` // for dirs, full path
}

func openBadgerStorage(path string) (*badgerStorage, error) {
	// Original panics when dir cannot be created; we return error mimicking panic-ish? Caller will handle.
	if err := os.MkdirAll(path, 0755); err != nil {
		// original panics
		panic(fmt.Sprintf("Error Creating Dir: %q err: %v", path, err))
	}
	bs := &badgerStorage{Path: path, Data: &badgerData{Dirs: make(map[string]*badgerDirRecord)}}
	bs.loadFile()
	return bs, nil
}
func (bs *badgerStorage) filePath() string { return filepath.Join(bs.Path, "storage.json") }
func (bs *badgerStorage) loadFile() {
	// custom binary format using report JSON? We'll use encoding/json via separate file
	data, err := os.ReadFile(bs.filePath())
	if err != nil { return }
	_ = jsonUnmarshal(data, bs.Data)
	if bs.Data.Dirs == nil { bs.Data.Dirs = make(map[string]*badgerDirRecord) }
}
func (bs *badgerStorage) saveFile() error {
	data, err := jsonMarshal(bs.Data)
	if err != nil { return err }
	return os.WriteFile(bs.filePath(), data, 0600)
}

// store a scanned root into badger storage: store each dir keyed by its absolute path
func (bs *badgerStorage) storeDirTree(root *Dir) error {
	var walk func(d *Dir)
	walk = func(d *Dir) {
		rec := &badgerDirRecord{Path: d.GetPath(), Dir: itemToBadger(d, d.GetPath()), Top: root.GetName()}
		for _, ch := range d.Files {
			rec.Children = append(rec.Children, itemToBadger(ch, ""))
			if sub, ok := ch.(*Dir); ok {
				// child path computed
				rec.Children[len(rec.Children)-1].ChildPath = sub.GetPath()
				walk(sub)
			}
		}
		bs.Data.Dirs[d.GetPath()] = rec
	}
	walk(root)
	return bs.saveFile()
}
func itemToBadger(it Item, path string) *badgerItem {
	bi := &badgerItem{Name: it.GetName(), IsDir: it.IsDir(), Size: it.GetSize(), Usage: it.GetUsage(), Mtime: it.GetMtime().Unix(), Count: it.GetItemCount()}
	if d, ok := it.(*Dir); ok { bi.IsArchive = d.IsArchive; bi.Flag = d.GetFlag() }
	if f, ok := it.(*File); ok { bi.Mli = f.Mli; bi.Hlnkc = f.Hlnkc; bi.NotReg = f.NotReg; bi.Flag = f.GetFlag() }
	return bi
}

func (bs *badgerStorage) loadDirTree(path string) (*Dir, error) {
	rec, ok := bs.Data.Dirs[path]
	if !ok {
		return nil, fmt.Errorf("not found")
	}
	// Build recursively
	var build func(r *badgerDirRecord, parent *Dir) *Dir
	build = func(r *badgerDirRecord, parent *Dir) *Dir {
		name := r.Dir.Name
		// for root, Name stored as full path in Dir.Name (our Dir.Name for root is full)
		// But in record Dir.Name is GetName() which for root is full path; for subdirs it's base name
		// Distinguish: if parent nil, use stored name (full)
		d := &Dir{Name: name, Parent: parent, Size: r.Dir.Size, Usage: r.Dir.Usage, OwnSize: 4096, BaseMtime: time.Unix(r.Dir.Mtime,0), Mtime: time.Unix(r.Dir.Mtime,0), ItemCount: r.Dir.Count, Flag: r.Dir.Flag, IsArchive: r.Dir.IsArchive}
		// For subdirs, Dir.Name should be base name; our record stored GetName() which is base, ok.
		for _, ch := range r.Children {
			if ch.IsDir {
				childRec, ok := bs.Data.Dirs[ch.ChildPath]
				if !ok {
					// construct empty dir
					sd := &Dir{Name: ch.Name, Parent: d, Size: ch.Size, Usage: ch.Usage, OwnSize: 4096, BaseMtime: time.Unix(ch.Mtime,0), Mtime: time.Unix(ch.Mtime,0), ItemCount: ch.Count, Flag: ch.Flag, IsArchive: ch.IsArchive}
					d.Files = append(d.Files, sd)
				} else {
					sd := build(childRec, d)
					// Ensure name is base
					sd.Name = ch.Name
					d.Files = append(d.Files, sd)
				}
			} else {
				f := &File{Name: ch.Name, Parent: d, Size: ch.Size, Usage: ch.Usage, Mtime: time.Unix(ch.Mtime,0), Mli: ch.Mli, Hlnkc: ch.Hlnkc, NotReg: ch.NotReg}
				d.Files = append(d.Files, f)
			}
		}
		return d
	}
	root := build(rec, nil)
	// Root Name: record Dir.Name is full path (root.Name)
	return root, nil
}

