	}

	// SQLite DB creation (only when DbPath is sqlite-like) happens after runtime+output opening, before time filters
	isBadger := strings.HasSuffix(flags.DbPath, ".badger")
	var sqliteConn *sqliteDB
	if flags.DbPath != "" && !isBadger {
		db, err := createSQLiteAnalyzer(flags)
		if err != nil {
			// createSQLiteAnalyzer already wraps with "creating sqlite analyzer: "
			return err
		}
		sqliteConn = db
		defer db.close()
	}

	// time filters
	timeFilter, err := buildTimeFilter(flags)
	if err != nil {
		return fmt.Errorf("invalid time filter: %w", err)
	}

	// build analyzer
	analyzer, err := buildAnalyzer(flags, timeFilter)
	if err != nil {
		return err
	}

	scanPath := "."
	if len(args) > 0 {
		scanPath = args[0]
	}

	// Show disks
	if flags.ShowDisks {
		return printDisks(os.Stdout, flags)
	}

	// If input file in stdout mode (or general), handle before UI/terminal checks
	// But if TUI mode and input file, UI will load it later.
	if isStdoutUI {
		return runStdout(flags, analyzer, scanPath, outputWriter, sqliteConn, isBadger)
	}

	// Interactive UI
	return runInteractive(flags, analyzer, scanPath, sqliteConn, isBadger)
}

// buildAnalyzer logs ignore etc and returns analyzer (or error)
func buildAnalyzer(flags *Flags, tf *TimeFilter) (*Analyzer, error) {
	// Ignoring dirs
	logInfof("Ignoring dirs %s", strings.Join(flags.IgnoreDirs, ", "))
	ignoreAbs := make(map[string]bool)
	cwd, _ := os.Getwd()
	for _, d := range flags.IgnoreDirs {
		abs := d
		if !filepath.IsAbs(abs) {
			if cwd != "" {
				abs = filepath.Join(cwd, d)
			}
			if a2, err := filepath.Abs(abs); err == nil {
				abs = a2
			}
		} else {
			abs = filepath.Clean(abs)
		}
		ignoreAbs[abs] = true
	}
	// patterns: CLI first (compile), then from file override
	var patStrs []string
	patStrs = append(patStrs, flags.IgnoreDirPatterns...)
	if len(patStrs) > 0 {
		logInfof("Ignoring dir patterns %s", strings.Join(patStrs, ", "))
	}
	compiled, err := compilePatterns(patStrs)
	if err != nil {
		return nil, err
	}
	if flags.IgnoreFromFile != "" {
		logInfof("Reading ignoring dir patterns from file '%s'", flags.IgnoreFromFile)
		filePats, err := readIgnoreFile(flags.IgnoreFromFile)
		if err != nil {
			return nil, err
		}
		compiled, err = compilePatterns(filePats)
		if err != nil {
			return nil, err
		}
		patStrs = filePats
	}
	if flags.MaxCores > 0 {
		logInfof("Max cores set to %d", flags.MaxCores)
	}
	a := &Analyzer{
		Flags: flags,
		IgnoreDirsAbs: ignoreAbs,
		Patterns: compiled,
		PatternStrs: patStrs,
		TimeFilter: tf,
		Sequential: flags.SequentialScanning,
	}
	return a, nil
}

func compilePatterns(strs []string) ([]*regexpType, error) {
	var out []*regexpType
	for _, s := range strs {
		re, err := compileRegexp(s)
		if err != nil {
			return nil, err
		}
		out = append(out, re)
	}
	return out, nil
}

func readIgnoreFile(path string) ([]string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var out []string
	lines := strings.Split(string(data), "\n")
	for _, l := range lines {
		t := strings.TrimSpace(l)
		if t == "" {
			continue
		}
		out = append(out, t)
	}
	return out, nil
}

func runStdout(flags *Flags, analyzer *Analyzer, scanPath string, outputWriter *os.File, sqliteConn *sqliteDB, isBadger bool) error {
	// input file mode
	if flags.InputFile != "" {
		// open input file
		inFile, err := os.Open(flags.InputFile)
		if err != nil {
			return fmt.Errorf("opening input file: %w", err)
		}
		defer inFile.Close()
		if flags.OutputFile != "" {
			return fmt.Errorf("reading analysis: reading analysis is not possible while exporting")
		}
		dir, err := ReadAnalysisWithProgress(inFile, flags)
		if err != nil {
			return fmt.Errorf("reading analysis: %w", err)
		}
		// print according to summarize or normal (depth/top ignored)
		if flags.Summarize {
			printSummarize(os.Stdout, dir, flags)
		} else {
			printDirItems(os.Stdout, dir, flags)
		}
		return nil
	}

	// get dir via storage/scanning
	dir, isFromStorage, err := obtainDir(flags, analyzer, scanPath, sqliteConn, isBadger)
	if err != nil {
		return err
	}
	_ = isFromStorage

	// exporting?
	if flags.OutputFile != "" {
		var w *osFileWriter
		var outWriter ioWriter
		if flags.OutputFile == "-" {
			outWriter = os.Stdout
		} else {
			outWriter = outputWriter
		}
		_ = w
		if err := ExportAnalysis(dir, outWriter); err != nil {
			return fmt.Errorf("scanning dir: %w", err)
		}
		return nil
	}

	// printing modes (only if dir is not nil)
	if flags.Top > 0 {
		printTop(os.Stdout, dir, flags)
		return nil
	}
	if flags.Depth > 0 {
		printDepth(os.Stdout, dir, flags)
		return nil
	}
	if flags.Summarize {
		printSummarize(os.Stdout, dir, flags)
		return nil
	}
	printDirItems(os.Stdout, dir, flags)
	return nil
}

// obtainDir handles storage reading / scanning, saving to DB, etc.
func obtainDir(flags *Flags, analyzer *Analyzer, scanPath string, sqliteConn *sqliteDB, isBadger bool) (*Dir, bool, error) {
	absPath, _ := filepath.Abs(scanPath)
	// storage backed?
	if flags.DbPath != "" && isBadger {
		// Badger-like storage
		bs, err := openBadgerStorage(flags.DbPath) // may panic if cannot create - original panics; let panic propagate? Convert to panic as in original for missing parent
		if err != nil {
			return nil, false, err
		}
		if flags.ReadFromStorage {
			// stat check first: Analyzer.Analyze would stat; emulate
			if _, err := os.Stat(absPath); err != nil {
				return nil, false, err
			}
			logInfof("Analyzing path: %s", absPath)
			if d, err := bs.loadDirTree(absPath); err == nil {
				return d, true, nil
			}
			// fallback to scan
			dir, err := analyzerAnalyzeWithStorage(analyzer, scanPath, func(root *Dir) error {
				return bs.storeDirTree(root)
			})
			return dir, false, err
		}
		// scan and store
		dir, err := analyzerAnalyzeWithStorage(analyzer, scanPath, func(root *Dir) error {
			return bs.storeDirTree(root)
		})
		return dir, false, err
	}
	if flags.DbPath != "" && !isBadger {
		// SQLite
		if flags.ReadFromStorage {
			// stat check
			if _, err := os.Stat(absPath); err != nil {
				return nil, false, err
			}
			logInfof("Analyzing path: %s", absPath)
			if sqliteConn != nil {
				if d, err := loadFromSQLite(sqliteConn); err == nil {
					logInfof("Loading analysis from existing SQLite database")
					return d, true, nil
				}
			}
			// fallback to scan and store
			dir, err := analyzer.Analyze(scanPath)
			if err != nil {
				return nil, false, err
			}
			if sqliteConn != nil {
				// storing requires sequential-order like tree; our store function sorts children by name
				// But dir stats are already computed; storing will compute row sizes from dir.
				_ = storeToSQLite(sqliteConn, dir)
				// Reload to get storage behavior (duplicate sizes zeroed, flags)
				if d2, err := loadFromSQLite(sqliteConn); err == nil {
					return d2, false, nil
				}
			}
			return dir, false, nil
		}
		// scan and store
		dir, err := analyzer.Analyze(scanPath)
		if err != nil {
			return nil, false, err
		}
		if sqliteConn != nil {
			_ = storeToSQLite(sqliteConn, dir)
			if d2, err := loadFromSQLite(sqliteConn); err == nil {
				return d2, false, nil
			}
		}
		return dir, false, nil
	}
	// no DB
	dir, err := analyzerAnalyzeWithProgress(analyzer, scanPath, flags)
	if err != nil {
		return nil, false, err
	}
	return dir, false, nil
}

func analyzerAnalyzeWithStorage(analyzer *Analyzer, scanPath string, store func(*Dir) error) (*Dir, error) {
	dir, err := analyzer.Analyze(scanPath)
	if err != nil {
		return nil, err
	}
	if store != nil {
		_ = store(dir)
	}
	return dir, nil
}

func analyzerAnalyzeWithProgress(analyzer *Analyzer, scanPath string, flags *Flags) (*Dir, error) {
	// spinner progress if needed
	if flags.NonInteractive && !flags.NoProgress && isTerminal(os.Stdout) {
		return analyzeWithSpinner(analyzer, scanPath, flags)
	}
	return analyzer.Analyze(scanPath)
}

// ensure imports
var _ = sort.StringSlice{}
var _ = filepath.Base
EOF
"}

