func run(cmd *cobra.Command, args []string, flags *Flags) error {
	// Determine changed flags
	changed := make(map[string]bool)
	cmd.Flags().Visit(func(fl *cobraFlag) {
		changed[fl.Name] = true
	})
	// cfg file resolution if empty
	if flags.CfgFile == "" {
		flags.CfgFile = defaultConfigPath()
	}
	initialLogFile := flags.LogFile
	// open log file (initial)
	if err := openLogFile(initialLogFile); err != nil {
		return fmt.Errorf("opening log file: %w", err)
	}
	// read config
	applied := flags.applyConfigFile(changed)
	_ = applied
	// if config changed log file and CLI didn't, reopen
	if !changed["log-file"] && flags.LogFile != initialLogFile {
		if err := openLogFile(flags.LogFile); err != nil {
			return fmt.Errorf("opening log file: %w", err)
		}
	}
	// write config
	if flags.WriteConfig {
		if err := flags.writeConfig(); err != nil {
			return err
		}
	}
	if flags.ShowVersion {
		fmt.Printf("Version:\t %s\nBuilt time:\t %s\nBuilt user:\t %s\n", version, buildTime, buildUser)
		return nil
	}
	logInfof("Runtime flags: %v", *flags)

	if flags.Profiling {
		go func() {
			_ = http.ListenAndServe("localhost:6060", nil)
		}()
	}

	// decide UI mode early for output file opening
	isStdoutUI := flags.NonInteractive || flags.OutputFile != "" || !isTerminal(os.Stdout)
	// In stdout UI, output file opening precedes many validations (but disks with output also)
	var outputWriter *os.File
	var outputIsStdout bool
	if flags.OutputFile != "" && flags.OutputFile != "-" {
		// only for stdout mode? In TUI mode with -o, program goes stdout mode anyway, so ok.
		// If we're in TUI mode and output file is set, isStdoutUI is true due OutputFile != ""
		file, err := os.OpenFile(flags.OutputFile, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
		if err != nil {
			return fmt.Errorf("opening output file: %w", err)
		}
		outputWriter = file
		defer file.Close()
	} else if flags.OutputFile == "-" {
		outputIsStdout = true
		_ = outputIsStdout
	}

	// SQLite DB creation (only when DbPath is sqlite-like) happens after runtime+output opening, before time filters
	isBadger := strings.HasSuffix(flags.DbPath, ".badger")
