	if err != nil {
		return err
	}

	scanPath := "."
	if len(args) > 0 {
		scanPath = args[0]
	}

	// Show disks
	if flags.ShowDisks {
		return printDisks(os.Stdout, flags)
	}

	// If input file in stdout mode (or general), handle before UI/terminal checks
	// But if TUI mode and input file, UI will load it later.
	if isStdoutUI {
		return runStdout(flags, analyzer, scanPath, outputWriter, sqliteConn, isBadger)
	}

	// Interactive UI
	return runInteractive(flags, analyzer, scanPath, sqliteConn, isBadger)
}

