func run(cmd *cobra.Command, args []string, flags *Flags) error {
	// Determine changed flags
	changed := make(map[string]bool)
	cmd.Flags().Visit(func(fl *cobraFlag) {
		changed[fl.Name] = true
	})
	// cfg file resolution if empty
	if flags.CfgFile == "" {
		flags.CfgFile = defaultConfigPath()
	}
	initialLogFile := flags.LogFile
	// open log file (initial)
	if err := openLogFile(initialLogFile); err != nil {
		return fmt.Errorf("opening log file: %w", err)
	}
	// read config
	applied := flags.applyConfigFile(changed)
	_ = applied
	// if config changed log file and CLI didn't, reopen
	if !changed["log-file"] && flags.LogFile != initialLogFile {
		if err := openLogFile(flags.LogFile); err != nil {
			return fmt.Errorf("opening log file: %w", err)
		}
	}
	// write config
	if flags.WriteConfig {
		if err := flags.writeConfig(); err != nil {
			return err
		}
	}
