	}

	// get dir via storage/scanning
	dir, isFromStorage, err := obtainDir(flags, analyzer, scanPath, sqliteConn, isBadger)
	if err != nil {
		return err
	}
	_ = isFromStorage

	// exporting?
	if flags.OutputFile != "" {
		var w *osFileWriter
		var outWriter ioWriter
		if flags.OutputFile == "-" {
			outWriter = os.Stdout
		} else {
			outWriter = outputWriter
		}
		_ = w
		if err := ExportAnalysis(dir, outWriter); err != nil {
			return fmt.Errorf("scanning dir: %w", err)
