package main

import (
	"fmt"
	"io"
	"os"
	"strings"
	"time"
)

// Very simple spinner for stdout when TTY and non-interactive
type spinner struct {
	frames []rune
	idx int
	start time.Time
	last time.Time
	active bool
	analyzer *Analyzer
	items int64
	done chan struct{}
}

func analyzeWithSpinner(a *Analyzer, path string, flags *Flags) (*Dir, error) {
	// Count items via Analyzer callback? Our analyzer does not yet emit item counts.
	// We'll implement a lightweight spinner thread that prints "Scanning..." frames based on time.
	done := make(chan struct{})
	go func() {
		frames := []rune("⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏")
		i := 0
		ticker := time.NewTicker(100 * time.Millisecond)
		defer ticker.Stop()
		// initial blank clearing line like original: \r spaces \r
		fmt.Fprintf(os.Stdout, "\r%s\r", strings.Repeat(" ", 100))
		for {
			select {
			case <-done:
				fmt.Fprintf(os.Stdout, "\r%s\r", strings.Repeat(" ", 100))
				return
			case <-ticker.C:
				// They show total items/size but we don't have progress info; show generic Scanning...
				// To approximate, we will not include item counts if unknown.
				// Use analyzer's progress counters if set
				fmt.Fprintf(os.Stdout, "\r%s\r %c Scanning... Total items: %s size: %s", strings.Repeat(" ", 100), frames[i%len(frames)], redBold(fmt.Sprintf("%d", a.ProgressItems)), yellow(a.ProgressSizeStr()))
				i++
			}
		}
	}()
	dir, err := a.Analyze(path)
	close(done)
	// give spinner goroutine a moment to print clearing? Original finishes with calculating phase
	// Print calculating line quickly
	fmt.Fprintf(os.Stdout, "\r%s\r ⠇ Calculating disk usage...", strings.Repeat(" ", 100))
	fmt.Fprintf(os.Stdout, "\r%s\r", strings.Repeat(" ", 100))
	// small wait for spinner goroutine to clear (it also clears on done)
	time.Sleep(10 * time.Millisecond)
	return dir, err
}

func redBold(s string) string { return "\x1b[31;1m" + s + "\x1b[0;22m" }

