package main

import (
	"fmt"
	"os"
	"strings"
)

func checkScreenError() error {
	term := os.Getenv("TERM")
	if term == "" {
		return fmt.Errorf("error creating screen: terminal entry not found: term not set")
	}
	if term == "dumb" {
		return fmt.Errorf("error creating screen: terminal not cursor addressable")
	}
	// check terminfo availability via known terms
	known := map[string]bool{
		"xterm": true, "xterm-256color": true, "screen": true, "screen-256color": true, "tmux": true, "tmux-256color": true, "linux": true, "vt100": true, "ansi": true, "rxvt-unicode-256color": true, "alacritty": true, "foot": true, "wezterm": true, "kitty": true, "xterm-kitty": true,
	}
	if !known[term] {
		// check /usr/share/terminfo etc
		if len(term) > 0 {
			c := term[0]
			paths := []string{
				fmt.Sprintf("/usr/share/terminfo/%c/%s", c, term),
				fmt.Sprintf("/lib/terminfo/%c/%s", c, term),
				fmt.Sprintf("/etc/terminfo/%c/%s", c, term),
			}
			found := false
			for _, p := range paths {
				if _, err := os.Stat(p); err == nil { found = true; break }
			}
			// also hex first char dir
			if !found {
				hex := fmt.Sprintf("%02x", c)
				paths2 := []string{fmt.Sprintf("/usr/share/terminfo/%s/%s", hex, term), fmt.Sprintf("/lib/terminfo/%s/%s", hex, term)}
				for _, p := range paths2 { if _, err := os.Stat(p); err == nil { found = true; break } }
			}
			if !found {
				return fmt.Errorf("error creating screen: couldn't open terminfo ($TERM) file for %s: exit status 1", term)
			}
		}
	}
	return nil
}

func runTUI(flags *Flags, analyzer *Analyzer, scanPath string, sqliteConn *sqliteDB, isBadger bool, out *os.File) error {
	// full implementation in tui_app.go
	return runTUIApp(flags, analyzer, scanPath, sqliteConn, isBadger)
}

var _ = strings.TrimSpace
EOF
"}

