{"command":"cat > natural.go <<'EOF'
package main

import "unicode"

// naturalLess compares strings with numeric runs treated as numbers.
// More leading zeros sorts before fewer for equal numeric values (as observed).
func naturalLess(a, b string) bool {
	c := naturalCompare(a, b)
	return c < 0
}
func naturalCompare(a, b string) int {
	ar := []rune(a)
	br := []rune(b)
	i, j := 0, 0
	firstZeroDiff := 0
	for i < len(ar) && j < len(br) {
		ac, bc := ar[i], br[j]
		if unicode.IsDigit(ac) && unicode.IsDigit(bc) {
			// digit runs
			si, sj := i, j
			for i < len(ar) && unicode.IsDigit(ar[i]) { i++ }
			for j < len(br) && unicode.IsDigit(br[j]) { j++ }
			da := string(ar[si:i])
			db := string(br[sj:j])
			ta := trimLeadingZeros(da)
			tb := trimLeadingZeros(db)
			if len(ta) != len(tb) {
				if len(ta) < len(tb) { return -1 }
				return 1
			}
			if ta != tb {
				if ta < tb { return -1 }
				return 1
			}
			// numeric equal, remember zero difference
			if firstZeroDiff == 0 && len(da) != len(db) {
				// more zeros = smaller
				if len(da) > len(db) { firstZeroDiff = -1 } else { firstZeroDiff = 1 }
			}
			continue
		}
		if ac != bc {
			if ac < bc { return -1 }
			return 1
		}
		i++; j++
	}
	// one is prefix
	if i < len(ar) {
		return 1
	}
	if j < len(br) {
		return -1
	}
	return firstZeroDiff
}
func trimLeadingZeros(s string) string {
	i := 0
	for i < len(s) && s[i] == '0' { i++ }
	return s[i:]
}
EOF
