package main

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"
	"unicode/utf8"
)

// terminal low-level is in term.go

type parentItem struct { dir *Dir }
func (p *parentItem) GetName() string { return ".." }
func (p *parentItem) GetPath() string { return p.dir.GetPath() }
func (p *parentItem) GetSize() int64 { return p.dir.GetSize() }
func (p *parentItem) GetUsage() int64 { return p.dir.GetUsage() }
func (p *parentItem) GetMtime() time.Time { return p.dir.GetMtime() }
func (p *parentItem) IsDir() bool { return true }
func (p *parentItem) GetFlag() byte { return ' ' }
func (p *parentItem) GetItemCount() int { return p.dir.GetItemCount() }
func (p *parentItem) GetParent() *Dir { return p.dir.Parent }
func (p *parentItem) SetParent(d *Dir) {}

type collapsedItem struct {
	leaf *Dir
	raw *Dir
	rel string // e.g. a/b/c without leading slash
}
func (c *collapsedItem) GetName() string { return c.leaf.GetName() }
func (c *collapsedItem) GetPath() string { return c.leaf.GetPath() }
func (c *collapsedItem) GetSize() int64 { return c.leaf.GetSize() }
func (c *collapsedItem) GetUsage() int64 { return c.leaf.GetUsage() }
func (c *collapsedItem) GetMtime() time.Time { return c.leaf.GetMtime() }
func (c *collapsedItem) IsDir() bool { return true }
func (c *collapsedItem) GetFlag() byte { return c.leaf.GetFlag() }
func (c *collapsedItem) GetItemCount() int { return c.leaf.GetItemCount() }
func (c *collapsedItem) GetParent() *Dir { return c.leaf.Parent }
func (c *collapsedItem) SetParent(d *Dir) {}

type navFrame struct {
	dir *Dir
	cursor int
	offset int
}

type modalKind int
const (
	modalNone modalKind = iota
	modalConfirm // delete/empty
	modalExport
	modalError
	modalHelp
	modalInfo
)

type modalState struct {
	kind modalKind
	text string // for confirm/error
	action string // "delete" or "empty"
	items []Item // targets for delete/empty (underlying raw items or files)
	button int // 0 no,1 yes,2 dont ask
	exportText string
	exportFocus int //0 input,1 button
	exportCursor int
	errText string
}

type fileViewState struct {
	item Item
	path string
	lines []string // wrapped lines will be recomputed on resize
	rawLines []string
	offset int
}

type uiApp struct {
	flags *Flags
	analyzer *Analyzer
	root *Dir
	current *Dir
	stack []navFrame
	cursor int
	offset int
	sortBy string
	sortOrder string
	showCount bool
	showMtime bool
	showApparent bool
	showRelative bool
	searchActive bool
	searchText string
	marked map[Item]bool
	ignored map[Item]bool
	modal *modalState
	// info/help overlay booleans (modal field also used? keep separate flags but render after)
	infoOpen bool
	helpOpen bool
	view *fileViewState
	statusMsg string
	quit bool
	printPath bool
	term *terminal
	sqliteConn *sqliteDB
	isBadger bool
	scanPath string
	confirmDisabled bool // don't ask again this session
	progressItems int64
}

func runTUIApp(flags *Flags, analyzer *Analyzer, scanPath string, sqliteConn *sqliteDB, isBadger bool) error {
	// Obtain root (input, storage, scan) with progress rendering handled separately later (synchronous first version)
	var root *Dir
	var err error
	if flags.InputFile != "" {
		inFile, err2 := os.Open(flags.InputFile)
		if err2 != nil {
			return fmt.Errorf("opening input file: %w", err2)
		}
		defer inFile.Close()
		root, err = ReadAnalysis(inFile)
		if err != nil {
			return fmt.Errorf("reading analysis: %w", err)
		}
	} else {
		// Use obtainDir logic shared with stdout
		// But obtainDir logs "Analyzing path" etc. It also handles storage.
		root, _, err = obtainDir(flags, analyzer, scanPath, sqliteConn, isBadger)
		if err != nil {
			return err
		}
	}
	app := &uiApp{
		flags: flags,
		analyzer: analyzer,
		root: root,
		current: root,
		marked: make(map[Item]bool),
		ignored: make(map[Item]bool),
		sqliteConn: sqliteConn,
		isBadger: isBadger,
		scanPath: scanPath,
	}
	// sorting init
	app.sortBy = flags.Sorting.By
	app.sortOrder = flags.Sorting.Order
	if app.sortBy == "" {
		app.sortBy = "size"
		app.sortOrder = "desc"
	}
	app.showCount = flags.ShowItemCount
	app.showMtime = flags.ShowMTime
	app.showApparent = flags.ShowApparentSize
	app.showRelative = flags.ShowRelativeSize
	if flags.ChangeCwd {
		// change to root dir if it's a real dir
		if st, err := os.Stat(root.GetPath()); err == nil && st.IsDir() {
			_ = os.Chdir(root.GetPath())
		}
	}
	term, err := newTerminal()
	if err != nil {
		return err
	}
	app.term = term
	defer term.Close()
	if flags.Mouse {
		term.EnableMouse()
	}
	err = app.loop()
	if app.printPath {
		// after terminal closed via loop Close? We need close before printing
		term.Close()
		fmt.Println(app.current.GetPath())
	}
	return err
}

func (app *uiApp) visibleCount() int {
	h := app.term.Height()
	header := 1
	if app.flags.Style.Header.Hidden { header = 0 }
	vc := h - header - 1 - 1 // title + footer
	if vc < 1 { vc = 1 }
	return vc
}

// build display items: first entry may be parentItem, rest are display items (possibly collapsed)
func (app *uiApp) displayItems() []Item {
	var out []Item
	if app.current.Parent != nil {
		out = append(out, &parentItem{dir: app.current.Parent})
	}
	raw := app.sortedChildren(app.current.Files)
	for _, ch := range raw {
		// search filter applied later for display list, but parent always included
		// create display item
		var disp Item = ch
		if dir, ok := ch.(*Dir); ok && app.flags.CollapsePath {
			leaf, rel := collapseChain(dir)
			if leaf != dir {
				disp = &collapsedItem{leaf: leaf, raw: dir, rel: rel}
			}
		}
		if app.searchActive && app.searchText != "" {
			nameToCheck := disp.GetName()
			// also check raw name
			if !strings.Contains(strings.ToLower(nameToCheck), strings.ToLower(app.searchText)) && !strings.Contains(strings.ToLower(ch.GetName()), strings.ToLower(app.searchText)) {
				// also check display rel for collapsed
				if ci, ok := disp.(*collapsedItem); ok && strings.Contains(strings.ToLower(ci.rel), strings.ToLower(app.searchText)) {
					// include
				} else {
					continue
				}
			}
		}
		out = append(out, disp)
	}
	return out
}

func collapseChain(d *Dir) (*Dir, string) {
	leaf := d
	parts := []string{d.Name}
	for {
		if len(leaf.Files) != 1 { break }
		child, ok := leaf.Files[0].(*Dir)
		if !ok { break }
		leaf = child
		parts = append(parts, child.Name)
	}
	return leaf, strings.Join(parts, "/")
}

func (app *uiApp) sortedChildren(items []Item) []Item {
	out := make([]Item, len(items))
	copy(out, items)
	by := app.sortBy
	order := app.sortOrder
	sort.SliceStable(out, func(i, j int) bool {
		c := compareItemsUI(out[i], out[j], by, app)
		if order == "asc" {
			return c < 0
		}
		return c > 0
	})
	return out
}

func compareItemsUI(a, b Item, by string, app *uiApp) int {
	var c int
	switch by {
	case "name":
		c = naturalCompare(a.GetName(), b.GetName())
	case "size":
		av, bv := uiDisplaySize(a, app), uiDisplaySize(b, app)
		if av < bv { c = -1 } else if av > bv { c = 1 }
		if c == 0 { c = naturalCompare(a.GetName(), b.GetName()) }
	case "itemCount":
		av, bv := a.GetItemCount(), b.GetItemCount()
		if av < bv { c = -1 } else if av > bv { c = 1 }
		if c == 0 { c = naturalCompare(a.GetName(), b.GetName()) }
	case "mtime":
		at, bt := a.GetMtime(), b.GetMtime()
		if at.Before(bt) { c = -1 } else if at.After(bt) { c = 1 }
		if c == 0 { c = naturalCompare(a.GetName(), b.GetName()) }
	default:
		c = 0
	}
	return c
}

func uiDisplaySize(it Item, app *uiApp) int64 {
	if app.showApparent { return it.GetSize() }
	return it.GetUsage()
}

// footer stats based on raw children (not collapsed), filtered by search, excluding ignored
func (app *uiApp) footerStats() (usage int64, apparent int64, items int) {
	for _, ch := range app.current.Files {
		// search filter: check child name or collapsed leaf name
		if app.searchActive && app.searchText != "" {
			name := ch.GetName()
			ok := strings.Contains(strings.ToLower(name), strings.ToLower(app.searchText))
			if !ok {
				if dir, isDir := ch.(*Dir); isDir && app.flags.CollapsePath {
					leaf, rel := collapseChain(dir)
					if strings.Contains(strings.ToLower(leaf.GetName()), strings.ToLower(app.searchText)) || strings.Contains(strings.ToLower(rel), strings.ToLower(app.searchText)) { ok = true }
				}
			}
			if !ok { continue }
		}
		if app.ignored[ch] { continue }
		// also if collapsed leaf ignored
		if dir, ok := ch.(*Dir); ok && app.flags.CollapsePath {
			leaf, _ := collapseChain(dir)
			if app.ignored[leaf] { continue }
		}
		usage += ch.GetUsage()
		apparent += ch.GetSize()
		items += ch.GetItemCount()
	}
	return
}

func (app *uiApp) loop() error {
	// initial render
	for !app.quit {
		app.render()
		ev, err := app.term.ReadEvent()
		if err != nil {
			return nil
		}
		app.handleEvent(ev)
	}
	return nil
}

func (app *uiApp) ensureCursorVisible() {
	items := app.displayItems()
	if app.cursor >= len(items) { app.cursor = len(items)-1 }
	if app.cursor < 0 { app.cursor = 0 }
	vc := app.visibleCount()
	if app.cursor < app.offset { app.offset = app.cursor }
	if app.cursor >= app.offset+vc { app.offset = app.cursor - vc + 1 }
	if app.offset < 0 { app.offset = 0 }
	// also adjust offset if items shrink
	if app.offset > len(items) { app.offset = 0 }
}

func (app *uiApp) selectedItem() Item {
	items := app.displayItems()
	if len(items)==0 { return nil }
	if app.cursor <0 || app.cursor >= len(items) { return nil }
	return items[app.cursor]
}

func (app *uiApp) handleEvent(ev event) {
	// clear status message on any key (except it will be reset by actions)
	hadStatus := app.statusMsg != ""
	if ev.typ == evKey {
		// modal handling first
		if app.modal != nil {
			app.handleModalKey(ev)
			return
		}
		if app.view != nil {
			app.handleViewKey(ev)
			return
		}
		// search mode
		if app.searchActive {
			if app.handleSearchKey(ev) {
				return
			}
			// else fall through to normal handling for navigation etc?
		}
		// help/info closing / toggling precedence for q etc.
		// Normal keys
		app.handleNormalKey(ev)
		if hadStatus && app.statusMsg == "" {
			// already cleared above? We cleared at start? implement: if hadStatus, clear before actions unless action sets new
		}
	}
	if ev.typ == evResize {
		// just re-render
	}
	if ev.typ == evMouse {
		app.handleMouse(ev)
	}
}

// utility to set cursor to item index in current display list matching underlying item/dir
func (app *uiApp) setCursorToItem(target Item) {
	items := app.displayItems()
	for i, it := range items {
		if it == target {
			app.cursor = i; app.ensureCursorVisible(); return
		}
		// collapsed / underlying
		if ci, ok := it.(*collapsedItem); ok {
			if ci.leaf == target || ci.raw == target { app.cursor=i; app.ensureCursorVisible(); return }
		}
		if d, ok := target.(*Dir); ok {
			if it.GetPath() == d.GetPath() { app.cursor=i; app.ensureCursorVisible(); return }
		}
	}
}

var _ = filepath.Base
var _ = sort.StringSlice{}
var _ = utf8.RuneLen
EOF
"}

