package main

import (
	"os"
	"os/signal"
	"syscall"
	"unsafe"
)

type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Line   byte
	Cc     [32]byte
	Ispeed uint32
	Ospeed uint32
}

type winsize struct {
	Rows uint16
	Cols uint16
	X uint16
	Y uint16
}

type eventType int
const (
	evKey eventType = iota
	evResize
	evMouse
)

type event struct {
	typ eventType
	ch rune
	key string // special name: Up, Down, Left, Right, Enter, Escape, Backspace, Delete, PgUp, PgDn, Home, End, Tab, Space etc
	raw byte
	mouseX, mouseY int
	mouseButton int // 0 left press etc
	mouseRelease bool
}

type terminal struct {
	fd int
	oldState termios
	w, h int
	resizeCh chan os.Signal
	buf []byte
	mouse bool
	closed bool
}

func ioctlGetTermios(fd int) (termios, error) {
	var t termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5401), uintptr(unsafe.Pointer(&t)))
	if errno != 0 { return t, errno }
	return t, nil
}
func ioctlSetTermios(fd int, t *termios) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5402), uintptr(unsafe.Pointer(t)))
	if errno != 0 { return errno }
	return nil
}
func getWinSize(fd int) (int,int) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(0x5413), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 { return 80,24 }
	return int(ws.Cols), int(ws.Rows)
}

func newTerminal() (*terminal, error) {
	fd := int(os.Stdin.Fd())
	// tcell uses /dev/tty if stdin not tty? For now require stdin tty; if not, try open /dev/tty
	if !isTerminal(os.Stdin) {
		f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
		if err == nil {
			// replace stdin? keep separate - simplified: use that file for reading via reassign? We'll store fd and use os.NewFile duplicate
			// For event reading we use os.Stdin anyway in this implementation; opening tty may help in tmux cases where stdin is tty anyway.
			_ = f
			f.Close()
		}
	}
	old, err := ioctlGetTermios(fd)
	if err != nil {
		// try stdout fd
		fd = int(os.Stdout.Fd())
		old, err = ioctlGetTermios(fd)
		if err != nil { return nil, err }
	}
	t := &terminal{fd: fd, oldState: old}
	t.w, t.h = getWinSize(int(os.Stdout.Fd()))
	// raw mode
	raw := old
	raw.Iflag &^= (0x0001 | 0x0002 | 0x0010 | 0x0020 | 0x0040 | 0x0100) // BRKINT ICRNL INPCK ISTRIP IXON etc approximate
	raw.Oflag &^= 0x0001 // OPOST
	raw.Lflag &^= (0x0002 | 0x0001 | 0x0008 | 0x8000) // ECHO ICANON ISIG IEXTEN (?), ISIG we keep? tcell disables ISIG so Ctrl-C is a key
	// Actually need clear: ECHO=0x0008? On linux: ISIG 0x0001, ICANON 0x0002, ECHO 0x0008, ECHOE etc. Let's set correctly below
	raw.Lflag = old.Lflag &^ (0x0001 | 0x0002 | 0x0008 | 0x8000)
	raw.Cflag &^= (0x0100 | 0x0030) // PARENB CSIZE
	raw.Cflag |= 0x0020 // CS8
	raw.Cc[6] = 1 // VMIN
	raw.Cc[5] = 0 // VTIME
	if err := ioctlSetTermios(fd, &raw); err != nil { return nil, err }
	// enter alternate screen, hide cursor, clear
	os.Stdout.WriteString("\x1b[?1049h\x1b[?25l\x1b[H\x1b[2J")
	t.resizeCh = make(chan os.Signal, 1)
	signal.Notify(t.resizeCh, syscall.SIGWINCH)
	go func() {
		for range t.resizeCh {
			t.w, t.h = getWinSize(int(os.Stdout.Fd()))
		}
	}()
	return t, nil
}

func (t *terminal) EnableMouse() {
	t.mouse = true
	os.Stdout.WriteString("\x1b[?1000h\x1b[?1002h\x1b[?1015h\x1b[?1006h")
}
func (t *terminal) DisableMouse() {
	if t.mouse { os.Stdout.WriteString("\x1b[?1006l\x1b[?1015l\x1b[?1002l\x1b[?1000l"); t.mouse=false }
}

