// ReadEvent reads one key/mouse/resize event blocking
func (t *terminal) ReadEvent() (event, error) {
	// check resize via non-blocking? We rely on blocking stdin; resize signals interrupt read (EINTR) - Go os.File read may retry?
	for {
		b := make([]byte, 1)
		n, err := os.Stdin.Read(b)
		if err != nil {
			// if interrupted, return resize
			if t.w != func() int { w,_:=getWinSize(int(os.Stdout.Fd())); return w }() {
				t.w, t.h = getWinSize(int(os.Stdout.Fd()))
				return event{typ: evResize}, nil
			}
			return event{}, err
		}
		if n==0 { continue }
		c := b[0]
		if c == 0x1b {
			// try read sequence with short availability: peek using poll?
			seq, ev, isEv := t.readEscapeSequence()
			if isEv { return ev, nil }
			if len(seq)==0 {
				return event{typ: evKey, key: "Escape", raw: c}, nil
			}
			// if sequence returned a key event, return it
			return seqEvent(seq), nil
		}
		if c == '\r' || c == '\n' {
			return event{typ: evKey, key: "Enter", raw: c}, nil
		}
		if c == 0x7f {
			return event{typ: evKey, key: "Backspace", raw: c}, nil
		}
		if c == '\t' {
			return event{typ: evKey, key: "Tab", raw: c}, nil
		}
		if c == 0x03 {
			return event{typ: evKey, key: "CtrlC", raw: c}, nil
		}
		if c < 0x20 {
			// control keys as rune
			return event{typ: evKey, ch: rune(c), raw: c}, nil
		}
		// utf8 rune
		if c < 0x80 {
			if c == ' ' { return event{typ: evKey, key: "Space", ch: ' '}, nil }
			return event{typ: evKey, ch: rune(c)}, nil
		}
		// read rest of utf8
		buf := []byte{c}
		need := utf8Len(c)
		for len(buf) < need {
			bb := make([]byte,1)
			if _, err := os.Stdin.Read(bb); err != nil { break }
			buf = append(buf, bb[0])
		}
		r, _ := decodeRune(buf)
		return event{typ: evKey, ch: r}, nil
	}
}

func utf8Len(b byte) int {
	if b >= 0xf0 { return 4 }
	if b >= 0xe0 { return 3 }
	if b >= 0xc0 { return 2 }
	return 1
}
func decodeRune(b []byte) (rune,int) {
	r, sz := rune(b[0]), 1
	// use stdlib via converting to string
	s := string(b)
	for _, rr := range s { return rr, len(string(rr)) }
	return r, sz
}

func seqEvent(seq []byte) event {
	// seq includes ESC already? We'll define seq as bytes after ESC
	s := string(seq)
	switch s {
	case "[A": return event{typ: evKey, key: "Up"}
	case "[B": return event{typ: evKey, key: "Down"}
	case "[C": return event{typ: evKey, key: "Right"}
	case "[D": return event{typ: evKey, key: "Left"}
	case "OA": return event{typ: evKey, key: "Up"}
	case "OB": return event{typ: evKey, key: "Down"}
	case "OC": return event{typ: evKey, key: "Right"}
	case "OD": return event{typ: evKey, key: "Left"}
	case "[H": return event{typ: evKey, key: "Home"}
	case "[F": return event{typ: evKey, key: "End"}
	case "[5~": return event{typ: evKey, key: "PgUp"}
	case "[6~": return event{typ: evKey, key: "PgDn"}
	case "[3~": return event{typ: evKey, key: "Delete"}
	case "[Z": return event{typ: evKey, key: "Backtab"}
	default:
		// mouse SGR: [<b;x;yM or m
		if len(s) >= 3 && s[0]=='[' && s[1]=='<' {
			// parse
			var btn, x, y int
			release := false
			if s[len(s)-1]=='m' { release=true }
			// fmt Sscanf style manual
			parts := splitSemicolon(s[2:len(s)-1])
			if len(parts)==3 {
				btn = atoi(parts[0]); x=atoi(parts[1]); y=atoi(parts[2])
				return event{typ: evMouse, mouseButton: btn, mouseX: x, mouseY: y, mouseRelease: release}
			}
			_ = btn; _ = x; _ = y
		}
		return event{typ: evKey, key: "Unknown", raw: 0x1b}
	}
}

func splitSemicolon(s string) []string {
	var out []string; cur:=""
	for _,c:=range s { if c==';' { out=append(out,cur); cur="" } else { cur+=string(c) } }
	out=append(out,cur); return out
}
func atoi(s string) int { v:=0; neg:=false; for _,c:=range s { if c=='-' {neg=true; continue}; if c>='0'&&c<='9'{v=v*10+int(c-'0')} }; if neg{v=-v}; return v }

func (t *terminal) readEscapeSequence() ([]byte, event, bool) {
	// Use poll with short timeout to see if more bytes available
	// Set stdin to non-blocking temporarily? Use syscall Select
	fd := int(os.Stdin.Fd())
	// poll 30ms
	var rfds syscallFdSet
	fdSet(&rfds, fd)
	tv := syscall.Timeval{Sec:0, Usec: 30000}
	// syscall.Select signature differs; use Poll via syscall.Syscall SYS_POLL
	type pollfd struct { Fd int32; Events int16; Revents int16 }
	pfd := pollfd{Fd: int32(fd), Events: 0x1}
	_, _, errno := syscall.Syscall(syscall.SYS_POLL, uintptr(unsafe.Pointer(&pfd)), uintptr(1), uintptr(20))
	if errno != 0 || pfd.Revents==0 {
		return nil, event{}, false
	}
	// read next byte
	b := make([]byte,1)
	if _, err := os.Stdin.Read(b); err != nil { return nil, event{}, false }
	first := b[0]
	if first == '[' || first == 'O' {
		seq := []byte{first}
		// read until final byte (0x40-0x7e) or mouse etc
		for {
			// check final
			last := seq[len(seq)-1]
			if len(seq)>=2 && last >= 0x40 && last <= 0x7e && !(last=='[') {
				// For '[' sequences, final detection: if last is letter/~ etc and we have at least 2 bytes
				// Our loop reads one by one and checks after append
				break
			}
			// poll for more
			pfd.Revents=0
			_, _, errno := syscall.Syscall(syscall.SYS_POLL, uintptr(unsafe.Pointer(&pfd)), uintptr(1), uintptr(10))
			if errno!=0 || pfd.Revents==0 { break }
			bb := make([]byte,1)
			if _, err := os.Stdin.Read(bb); err != nil { break }
			seq = append(seq, bb[0])
			// final byte check
			c := bb[0]
			if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c=='~' || c=='M' || c=='m' {
				// But for mouse, need continue until M/m, which satisfies
				// For CSI, letters end.
				// However sequence like [200~ paste would end ~ ok
				break
			}
		}
		ev := seqEvent(seq)
		return nil, ev, true
	}
	// Alt+key: treat as escape then char
	// Return a key event for that char with Alt? Simplified return Escape
	// If byte is printable, return event for that rune
	if first < 0x80 {
		return nil, event{typ: evKey, ch: rune(first)}, true
	}
	return nil, event{}, false
}

type syscallFdSet struct { Bits [16]int64 }
func fdSet(set *syscallFdSet, fd int) { set.Bits[fd/64] |= 1 << (uint(fd)%64) }
EOF
