		if ignored && !isSel {
			// yellow
			yellowSt := style{fg: parseColor("#ffff00"), bold:true}
			// number style for ignored is also yellow? Original row entire yellow
			numSt = yellowSt; dSt=yellowSt; txtSt=yellowSt
			buf.write(x,y,string([]byte{flag}),yellowSt); x++
		} else {
			sty := txtSt; if isSel { sty=selSt }
			buf.write(x,y,string([]byte{flag}),sty); x++
		}
		if isParent {
			// blank size field: size width: space + 9 spaces? Actually row format: flag + space + %9s + space + bar(10)+sep
			// we'll fill spaces up to name position
			namePos := app.nameColumnX()
			// write spaces (already)
			// name
			sty := txtSt; if isSel { sty=selSt }
			buf.write(namePos, y, "/..", sty)
			continue
		}
		// size
		sizeVal := uiDisplaySize(it, app)
		sizeStr := formatSize(sizeVal, app.flags)
		// size field: space at x (currently 1) then %9s
		// we are at x=1
		sizeField := fmt.Sprintf("%9s", sizeStr)
		// number part styling: original colours number only; for simplicity colour number digits inside field: we need split field into spaces + number + space+unit
		// We'll draw field char by char: spaces as row style, number as numSt, unit as txtSt/sel
		{
			// parse sizeStr number/unit
			num, unit := splitSize(sizeStr)
			// field has leading spaces = 9-len(sizeStr)
			fx := x+1 // space separator is first char of? Actually format: flag(1) + space(1) + %9s
			// draw separator space
			sty:=txtSt; if isSel{sty=selSt}
			buf.write(fx-1,y," ",sty)
			// Wait re-evaluate: x is after flag (=1). The next char index should be 1 = space, then field 2-10.
			// Our fx calculation: field start=2
			fieldStart:=2
			// leading spaces
			lead := 9-len(sizeStr); if lead<0{lead=0}
			// draw field
			pos:=fieldStart
			for i:=0;i<lead;i++ { buf.write(pos,y," ",sty); pos++ }
			// number
			nsty:=numSt; if isSel{nsty=selSt}
			pos = buf.write(pos,y,num,nsty)
			if unit!="" {
				pos = buf.write(pos,y," "+unit,sty)
			}
			x = 11 // space after size at index11 will be drawn below
		}
		// bar
		barStart := 12
		bar := app.makeBar(it)
		sty:=txtSt; if isSel{sty=selSt}
		buf.write(11,y," ",sty)
		if app.flags.NoUnicode || app.flags.Style.UseOldSizeBar {
			// [bar]
			buf.write(barStart,y,"[",sty)
			buf.write(barStart+1,y,bar,sty)
			buf.write(barStart+11,y,"]",sty)
			buf.write(barStart+12,y," ",sty)
		} else {
			buf.write(barStart,y,bar,sty)
			buf.write(barStart+10,y,"▏",sty)
		}
		// columns after separator
		nameX := app.nameColumnX()
		colX := nameX
		// we need to draw count/mtime before name: they start right after separator
		afterSep := 23
		if app.flags.NoUnicode || app.flags.Style.UseOldSizeBar { afterSep = 25 }
		cx:=afterSep
		if app.showCount {
			cntStr := fmt.Sprintf("%6d", displayItemCount(it))
			cx = buf.write(cx,y,cntStr,sty)
			cx = buf.write(cx,y," ",sty)
		}
		if app.showMtime {
			mtStr := it.GetMtime().Format("2006-01-02 15:04:05")
			cx = buf.write(cx,y,mtStr,sty)
			cx = buf.write(cx,y," ",sty)
		}
		_ = colX
		// marked prefix
		nameSty := txtSt
		if it.IsDir() && !isSel && !ignored { nameSty = dSt }
		if isSel { nameSty = selSt }
		if ignored && !isSel { nameSty = numSt }
		prefix := ""
		if len(app.marked)>0 {
			if app.marked[it] || app.marked[underlyingItem(it)] { prefix="✓ " } else { prefix="  " }
		}
		name := displayName(it)
		if ci, ok := it.(*collapsedItem); ok { name = "/" + ci.rel }
		buf.write(cx,y,prefix+name,nameSty)
	}
}

func displayItemCount(it Item) int {
	if d, ok := it.(*Dir); ok {
		// UI count: descendants excluding dir itself
		c:=d.GetItemCount()-1; if c<0{c=0}; return c
	}
	if ci, ok := it.(*collapsedItem); ok {
		c:=ci.leaf.GetItemCount()-1; if c<0{c=0}; return c
	}
	return 1
}

func (app *uiApp) nameColumnX() int {
	x:=23
	if app.flags.NoUnicode || app.flags.Style.UseOldSizeBar { x=25 }
	if app.showCount { x+=7 }
	if app.showMtime { x+=20 }
	return x
}

func (app *uiApp) makeBar(it Item) string {
	size := uiDisplaySize(it, app)
	if app.ignored[it] || app.ignored[underlyingItem(it)] {
		if app.flags.NoUnicode || app.flags.Style.UseOldSizeBar {
			return strings.Repeat(" ",10)
		}
		return strings.Repeat(" ",10)
	}
	var total int64
	var denom int64
	if app.showRelative {
		// max among displayed raw children
		for _, ch := range app.current.Files {
			v:=uiDisplaySize(ch, app)
			if !app.isIgnored(ch) && v>denom { denom=v }
		}
	} else {
		usage, apparent, _ := app.footerStats()
		if app.showApparent { denom=apparent } else { denom=usage }
		_ = total
	}
	if denom<=0 || size<=0 {
		return strings.Repeat(" ",10)
	}
	ratio := float64(size)/float64(denom)
	if ratio>1 {ratio=1}
	if app.flags.NoUnicode || app.flags.Style.UseOldSizeBar {
		n := int(ratio*10) // floor
		if n>10{n=10}
		return strings.Repeat("#",n)+strings.Repeat(" ",10-n)
	}
	blocks := ratio*10
	full := int(blocks)
	frac := blocks - float64(full)
	parts := []rune{' ','▏','▎','▍','▌','▋','▊','▉','█'}
	var sb strings.Builder
	for i:=0;i<full && i<10;i++ { sb.WriteRune('█') }
	if full<10 {
		idx:= int(frac*8) // floor
		if idx>0 {
			if idx>8{idx=8}
			sb.WriteRune(parts[idx])
		}
	}
	// pad to 10 runes
	for len([]rune(sb.String()))<10 { sb.WriteRune(' ') }
	return sb.String()
}

func (app *uiApp) isIgnored(it Item) bool {
	if app.ignored[it] { return true }
	u := underlyingItem(it)
	if u!=nil && app.ignored[u] { return true }
	return false
}
func underlyingItem(it Item) Item {
	if ci, ok := it.(*collapsedItem); ok { return ci.leaf }
	return it
}
func underlyingRaw(it Item) Item {
	if ci, ok := it.(*collapsedItem); ok { return ci.raw }
	if pi, ok := it.(*parentItem); ok { return pi.dir }
	return it
}

func (app *uiApp) drawFileView(buf *screenBuf, start, end int) {
	if app.view == nil { return }
	lines := app.view.wrappedLines(buf.w)
	vc := end-start
	for i:=0;i<vc;i++ {
		idx:=app.view.offset+i
		if idx>=len(lines){break}
		buf.write(0,start+i,lines[idx], style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}})
	}
}
func (fv *fileViewState) wrappedLines(w int) []string {
	if w<=0 {w=80}
	var out []string
	for _, raw := range fv.rawLines {
		if raw=="" { out=append(out,""); continue }
		// wrap by runes width w
		r := []rune(raw)
		for len(r)>w {
			out=append(out,string(r[:w])); r=r[w:]
		}
		out=append(out,string(r))
	}
	return out
}

var _ = time.Now
EOF
"}

