package main

import (
	"fmt"
	"os"
	"strings"
	"time"
)

type colorSpec struct {
	isDefault bool
	code int // palette index 0-255, or -1
	rgb [3]int
	hasRGB bool
	name string
}

func parseColor(s string) colorSpec {
	if s == "" { return colorSpec{isDefault: true} }
	if strings.HasPrefix(s, "#") {
		hex := s[1:]
		if len(hex)==3 {
			var r,g,b int
			fmt.Sscanf(hex, "%1x%1x%1x", &r,&g,&b)
			return colorSpec{rgb: [3]int{r*17,g*17,b*17}, hasRGB: true}
		}
		if len(hex)>=6 {
			var r,g,b int
			fmt.Sscanf(hex[:6], "%02x%02x%02x", &r,&g,&b)
			return colorSpec{rgb: [3]int{r,g,b}, hasRGB: true}
		}
		return colorSpec{rgb: [3]int{0,0,0}, hasRGB: true}
	}
	// named colors map to RGB
	if rgb, ok := namedColors[strings.ToLower(s)]; ok {
		return colorSpec{rgb: rgb, hasRGB: true}
	}
	// invalid -> black
	return colorSpec{rgb: [3]int{0,0,0}, hasRGB: true}
}

var namedColors = map[string][3]int{
	"black": {0,0,0}, "white": {255,255,255}, "red": {255,0,0}, "green": {0,255,0}, "blue": {0,0,255},
	"yellow": {255,255,0}, "orange": {255,165,0}, "gray": {128,128,128}, "grey": {128,128,128},
	"darkgray": {169,169,169}, "darkgrey": {169,169,169}, "magenta": {255,0,255}, "cyan": {0,255,255},
	"pink": {255,192,203}, "brown": {165,42,42}, "lime": {0,255,0}, "olive": {128,128,0},
	"navy": {0,0,128}, "teal": {0,128,128}, "maroon": {128,0,0}, "purple": {128,0,128}, "silver":{192,192,192},
	"gold": {255,215,0}, "violet": {238,130,238},
}

// convert RGB to xterm palette index
func rgbToPalette(rgb [3]int) int {
	// palette 0-15 VGA
	vga := [][3]int{{0,0,0},{128,0,0},{0,128,0},{128,128,0},{0,0,128},{128,0,128},{0,128,128},{192,192,192},{128,128,128},{255,0,0},{0,255,0},{255,255,0},{0,0,255},{255,0,255},{0,255,255},{255,255,255}}
	best := 0; bestDist := 1<<62
	for i,c := range vga {
		d := dist2(rgb,c); if d<bestDist {bestDist=d; best=i}
	}
	levels := []int{0,95,135,175,215,255}
	for r:=0;r<6;r++ { for g:=0;g<6;g++ { for b:=0;b<6;b++ {
		idx := 16 + 36*r+6*g+b
		c := [3]int{levels[r],levels[g],levels[b]}
		d := dist2(rgb,c); if d<bestDist {bestDist=d; best=idx}
	}}}
	for i:=0;i<24;i++ {
		v := 8+10*i
		idx:=232+i; c:=[3]int{v,v,v}; d:=dist2(rgb,c); if d<bestDist {bestDist=d; best=idx}
	}
	return best
}
func dist2(a,b [3]int) int { dr:=a[0]-b[0]; dg:=a[1]-b[1]; db:=a[2]-b[2]; return dr*dr+dg*dg+db*db }

func sgrForColor(c colorSpec, isBg bool) string {
	if c.isDefault {
		if isBg { return "49" }
		return "39"
	}
	pal := rgbToPalette(c.rgb)
	if pal < 8 {
		if isBg { return fmt.Sprintf("%d", 40+pal) }
		return fmt.Sprintf("%d", 30+pal)
	}
	if pal < 16 {
		if isBg { return fmt.Sprintf("%d", 100+(pal-8)) }
		return fmt.Sprintf("%d", 90+(pal-8))
	}
	if isBg { return fmt.Sprintf("48;5;%d", pal) }
	return fmt.Sprintf("38;5;%d", pal)
}

type style struct {
	fg colorSpec
	bg colorSpec
	bold bool
}
func (s style) ansiStart() string {
	var codes []string
	if s.bold { codes = append(codes, "1") }
	if !s.fg.isDefault || true { codes = append(codes, sgrForColor(s.fg,false)) }
	// bg only if not default? For default bg we still emit 49 in some places to match tcell? We'll include if bg not default
	if !s.bg.isDefault { codes = append(codes, sgrForColor(s.bg,true)) }
	if len(codes)==0 { return "" }
	return "\x1b["+strings.Join(codes,";")+"m"
}
func styleReset() string { return "\x1b[0m\x1b[39m\x1b[49m" }
// More precise resets used by original (0;22 etc) are not needed for tmux text capture.

// cell buffer
type cell struct {
	ch rune
	sty style
}
type screenBuf struct {
	w,h int
	cells []cell
	def style
}
func newBuf(w,h int) *screenBuf {
	b := &screenBuf{w:w,h:h, def: style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}}
	b.cells = make([]cell, w*h)
	for i:= range b.cells { b.cells[i]=cell{ch:' ', sty:b.def} }
	return b
}
func (b *screenBuf) set(x,y int, ch rune, sty style) {
	if x<0||x>=b.w||y<0||y>=b.h {return}
	b.cells[y*b.w+x]=cell{ch:ch, sty:sty}
}
func (b *screenBuf) write(x,y int, s string, sty style) int {
	cx:=x
	for _, r := range s {
		if r=='\n' { break }
		// width: assume 1 for most, wide runes (blocks are 1)
		b.set(cx,y,r,sty); cx++
	}
	return cx
}
func (b *screenBuf) fillRow(y int, sty style) {
	for x:=0;x<b.w;x++ { b.cells[y*b.w+x]=cell{ch:' ', sty:sty} }
}
func (b *screenBuf) fillRect(x,y,w,h int, sty style) {
	for yy:=y; yy<y+h; yy++ { for xx:=x; xx<x+w; xx++ { b.set(xx,yy,' ',sty)}}
}

func (app *uiApp) render() {
	if app.term == nil { return }
	w,h := app.term.Size()
	app.term.w, app.term.h = w,h
	buf := newBuf(w,h)
	app.draw(buf)
	// serialize
	var sb strings.Builder
	sb.WriteString("\x1b[H")
	curStyle := style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	// We'll emit per row with style transitions
	for y:=0;y<h;y++ {
		if y>0 { sb.WriteString("\r\n") }
		// move to row start
		// we are sequential after \r\n, ok
		x:=0
		for x<w {
			c := buf.cells[y*w+x]
			if c.sty != curStyle {
				sb.WriteString("\x1b[0m")
				if c.sty.bold || !c.sty.fg.isDefault || !c.sty.bg.isDefault {
					sb.WriteString(c.sty.ansiStart())
				}
				curStyle = c.sty
			}
			sb.WriteRune(c.ch)
			x++
		}
		// reset at end of line to avoid bg leaking? Original resets per line
		sb.WriteString("\x1b[0m\x1b[39m\x1b[49m")
		curStyle = style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	}
	os.Stdout.WriteString(sb.String())
}

func (app *uiApp) styles() (headerStyle, footerStyle, titleStyle, numberStyle, dirStyle, selectedStyle, defaultStyle style) {
	fl := app.flags
	headerStyle = style{fg: parseColor(fl.Style.Header.TextColor), bg: parseColor(fl.Style.Header.BackgroundColor)}
	footerStyle = style{fg: parseColor(fl.Style.Footer.TextColor), bg: parseColor(fl.Style.Footer.BackgroundColor)}
	// numbers in footer
	titleStyle = style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}, bold:true}
	numberStyle = style{fg: parseColor(fl.Style.ResultRow.NumberColor), bold:true}
	dirStyle = style{fg: parseColor(fl.Style.ResultRow.DirectoryColor), bold:true}
	// selected default: white on green bold
	if fl.Style.SelectedRow.TextColor=="" && fl.Style.SelectedRow.BackgroundColor=="" {
		selectedStyle = style{fg: parseColor("#ffffff"), bg: parseColor("#00cd00"), bold:true}
		// palette conversion for white->97, green->42 via rgb match: #00cd00 is vga green (2) gives 42 bg - good
		selectedStyle.bg = colorSpec{rgb:[3]int{0,205,0}, hasRGB:true}
	} else {
		fg := parseColor(fl.Style.SelectedRow.TextColor); if fl.Style.SelectedRow.TextColor=="" { fg=parseColor("#ffffff") }
		bg := parseColor(fl.Style.SelectedRow.BackgroundColor); if fl.Style.SelectedRow.BackgroundColor=="" { bg=colorSpec{rgb:[3]int{0,205,0},hasRGB:true} }
		selectedStyle = style{fg: fg, bg:bg, bold:true}
	}
	defaultStyle = style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	return
}

func (app *uiApp) draw(buf *screenBuf) {
	w,h := buf.w, buf.h
	headerSt, footerSt, titleSt, numberSt, dirSt, selSt, defSt := app.styles()
	footerNumberSt := style{fg: parseColor(app.flags.Style.Footer.NumberColor), bg: parseColor(app.flags.Style.Footer.BackgroundColor), bold:true}
	footerStFull := style{fg: parseColor(app.flags.Style.Footer.TextColor), bg: parseColor(app.flags.Style.Footer.BackgroundColor)}
	_ = footerSt
	y:=0
	if !app.flags.Style.Header.Hidden {
		if y<h {
			buf.fillRow(y, headerSt)
			txt := " gdu ~ Use arrow keys to navigate, press ? for help "
			if app.statusMsg != "" { txt = " " + app.statusMsg }
			buf.write(0,y,txt,headerSt)
		}
		y++
	}
	// title
	if y<h {
		title := ""
		if app.view != nil {
			title = fmt.Sprintf(" --- %s ---", app.view.path)
		} else {
			title = fmt.Sprintf(" --- %s ---", app.current.GetPath())
		}
		// fill row with default
		buf.write(0,y,title,titleSt)
	}
	titleRow := y
	y++
	// content area
	contentStart := y
	contentEnd := h-1 // exclusive, footer at h-1
	if contentEnd < contentStart { contentEnd = contentStart }
	if app.view != nil {
		app.drawFileView(buf, contentStart, contentEnd)
	} else {
		app.drawList(buf, contentStart, contentEnd, numberSt, dirSt, selSt, defSt)
	}
	_ = titleRow
	// footer
	if h>0 {
		fy:=h-1
		buf.fillRow(fy, footerStFull)
		if app.searchActive {
			// input field first 17 chars
			txt := app.searchText
			// draw search text at 0
			buf.write(0,fy,txt,footerStFull)
			// footer info after 17
			usage, apparent, items := app.footerStats()
			footerTxt := fmt.Sprintf("Total disk usage: %s Apparent size: %s Items: %d Sorting by: %s %s", formatSizePlain(usage, app.flags), formatSizePlain(apparent, app.flags), items, app.sortBy, app.sortOrder)
			// draw styled footer segments starting at 17
			app.drawFooterText(buf, 17, fy, footerTxt, footerStFull, footerNumberSt)
		} else {
			usage, apparent, items := app.footerStats()
			markedCount := len(app.marked)
			var sb strings.Builder
			sb.WriteString(" ")
			if markedCount>0 { sb.WriteString(fmt.Sprintf("Selected items: %d ", markedCount)) }
			// We will draw footer with number styling manually via segments
			// Build segments: " Total...: " + number etc
			// For simplicity draw plain then overlay numbers? We'll use drawFooterSegments
			app.drawFooterSegments(buf, fy, usage, apparent, items, footerStFull, footerNumberSt)
			_ = sb
		}
	}
	// modals / overlays on top
	if app.infoOpen {
		app.drawInfo(buf)
	}
	if app.helpOpen {
		app.drawHelp(buf)
	}
	if app.modal != nil {
		app.drawModal(buf)
	}
}

func formatSizePlain(size int64, f *Flags) string { return formatSize(size,f) }

// footer segments
func (app *uiApp) drawFooterSegments(buf *screenBuf, y int, usage, apparent int64, items int, base style, num style) {
	x:=0
	write := func(s string, sty style) { x = buf.write(x,y,s,sty) }
	// numbers separated
	uNum, uUnit := splitSize(formatSize(usage, app.flags))
	aNum, aUnit := splitSize(formatSize(apparent, app.flags))
	if len(app.marked)>0 {
		write(fmt.Sprintf(" Selected items: %d ", len(app.marked)), base)
	} else {
		write(" ", base)
	}
	write("Total disk usage: ", base)
	write(uNum, num)
	if uUnit!="" { write(" "+uUnit, base) }
	write(" Apparent size: ", base)
	write(aNum, num)
	if aUnit!="" { write(" "+aUnit, base) }
	write(fmt.Sprintf(" Items: "), base)
	write(fmt.Sprintf("%d", items), num)
	write(fmt.Sprintf(" Sorting by: %s %s", app.sortBy, app.sortOrder), base)
}
func (app *uiApp) drawFooterText(buf *screenBuf, x int, y int, txt string, base style, num style) {
	// simple: draw as base (numbers not styled differently for search? original likely still styled, but ok)
	buf.write(x,y,txt,base)
	_ = num
}

func (app *uiApp) drawList(buf *screenBuf, start, end int, numberSt, dirSt, selSt, defSt style) {
	app.ensureCursorVisible()
	items := app.displayItems()
	vc := end-start
	// draw rows
	for row:=0; row<vc; row++ {
		idx := app.offset+row
		y := start+row
		if idx >= len(items) { break }
		it := items[idx]
		isSel := idx==app.cursor
		rowStyle := defSt
		if isSel { rowStyle = selSt; buf.fillRow(y, selSt) }
		// flag
		x:=0
		// parent item has blank size etc
		_, isParent := it.(*parentItem)
		// flag char
		flag := it.GetFlag()
		if isParent { flag=' ' }
		ignored := app.isIgnored(it)
		// styles for non-selected
		numSt := numberSt; dSt:=dirSt; txtSt:=defSt
		if ignored && !isSel {
			// yellow
			yellowSt := style{fg: parseColor("#ffff00"), bold:true}
			// number style for ignored is also yellow? Original row entire yellow
			numSt = yellowSt; dSt=yellowSt; txtSt=yellowSt
			buf.write(x,y,string([]byte{flag}),yellowSt); x++
		} else {
			sty := txtSt; if isSel { sty=selSt }
			buf.write(x,y,string([]byte{flag}),sty); x++
		}
		if isParent {
			// blank size field: size width: space + 9 spaces? Actually row format: flag + space + %9s + space + bar(10)+sep
			// we'll fill spaces up to name position
			namePos := app.nameColumnX()
			// write spaces (already)
			// name
			sty := txtSt; if isSel { sty=selSt }
			buf.write(namePos, y, "/..", sty)
			continue
		}
		// size
		sizeVal := uiDisplaySize(it, app)
		sizeStr := formatSize(sizeVal, app.flags)
		// size field: space at x (currently 1) then %9s
		// we are at x=1
		sizeField := fmt.Sprintf("%9s", sizeStr)
		// number part styling: original colours number only; for simplicity colour number digits inside field: we need split field into spaces + number + space+unit
		// We'll draw field char by char: spaces as row style, number as numSt, unit as txtSt/sel
		{
			// parse sizeStr number/unit
			num, unit := splitSize(sizeStr)
			// field has leading spaces = 9-len(sizeStr)
			fx := x+1 // space separator is first char of? Actually format: flag(1) + space(1) + %9s
