		app.handleNormalKey(ev); return true
	case "Space":
		app.searchText+=" "; app.cursor= firstIndexAfterParent(app); return true
	default:
		if ev.ch!=0 {
			// Printable rune including letters that are also commands (q etc) should be typed
			app.searchText+=string(ev.ch)
			app.cursor= firstIndexAfterParent(app)
			return true
		}
	}
	return false
}
func firstIndexAfterParent(app *uiApp) int {
	if app.current.Parent!=nil { return 0 } // parent is first, but search selected should be first matching item? Original after typing, selected is first filtered item (in root no parent)
	// In root, cursor 0 is first filtered. In subdir, cursor 0 is ".." which is shown - original selected ".." after typing in subdir.
	return 0
}

func (app *uiApp) handleViewKey(ev event) {
	switch ev.key {
	case "Escape":
		app.view=nil; return
	case "Left":
		app.view=nil; return
	case "Up":
		if app.view.offset>0{app.view.offset--}; return
	case "Down":
		app.view.offset++; app.clampViewOffset(); return
	case "PgUp":
		app.view.offset-=app.viewPageSize(); if app.view.offset<0{app.view.offset=0}; return
	case "PgDn":
		app.view.offset+=app.viewPageSize(); app.clampViewOffset(); return
	case "Home":
		app.view.offset=0; return
	case "End":
		app.view.offset=1<<30; app.clampViewOffset(); return
	default:
		if ev.ch=='q' { app.view=nil; return }
		if ev.ch=='g' { app.view.offset=0; return }
		if ev.ch=='G' { app.view.offset=1<<30; app.clampViewOffset(); return }
		if ev.ch=='k' { if app.view.offset>0{app.view.offset--}; return }
		if ev.ch=='j' { app.view.offset++; app.clampViewOffset(); return }
		if ev.key=="CtrlC" { app.quit=true; return }
	}
}
func (app *uiApp) viewPageSize() int {
	h:=app.term.Height(); header:=1; if app.flags.Style.Header.Hidden{header=0}; vc:=h-header-1-1; if vc<1{vc=1}; return vc
}
func (app *uiApp) clampViewOffset() {
	if app.view==nil{return}
	lines:=app.view.wrappedLines(app.term.Width())
	maxOff:=len(lines)-app.viewPageSize(); if maxOff<0{maxOff=0}; if app.view.offset>maxOff{app.view.offset=maxOff}; if app.view.offset<0{app.view.offset=0}
}

func (app *uiApp) handleMouse(ev event) {
	if ev.mouseRelease { return }
	// button 0 left press, 64 wheel up, 65 wheel down in SGR encoding
	if ev.mouseButton==64 { app.moveCursor(-3); return }
	if ev.mouseButton==65 { app.moveCursor(3); return }
	if ev.mouseButton==0 {
		// click on list rows
		header:=1; if app.flags.Style.Header.Hidden{header=0}
		row:=ev.mouseY - (header+1) // 1-based y: row index =?
		// mouseY is 1-based terminal row. List starts at header+title (rows: header at1, title2, list starts3 => index = y-3)
		idx:= app.offset + (ev.mouseY - (header+2))
		_ = row
		items:=app.displayItems()
		if idx>=0 && idx < len(items) {
			if idx==app.cursor {
				// second click - enter
				app.enterItem()
			} else {
				app.cursor=idx; app.ensureCursorVisible()
			}
		}
	}
}

EOF
"}

