{"command":"cat > tui_modal.go <<'EOF'
package main

import (
	"fmt"
	"strings"
)

func (app *uiApp) handleModalKey(ev event) {
	m := app.modal
	if m == nil { return }
	switch m.kind {
	case modalConfirm:
		switch ev.key {
		case "Left":
			m.button = (m.button+2)%3
		case "Right", "Tab":
			m.button = (m.button+1)%3
		case "Enter":
			if m.button==0 {
				app.modal=nil
			} else {
				if m.button==2 { app.confirmDisabled=true }
				targets:=m.items; isEmpty:=m.action=="empty"
				app.modal=nil
				app.doDeleteOrEmpty(targets, isEmpty)
			}
		case "Escape":
			app.modal=nil
		default:
			if ev.key=="CtrlC" { app.quit=true }
		}
	case modalExport:
		if m.exportFocus==0 {
			switch ev.key {
			case "Escape":
				app.modal=nil
			case "Tab":
				m.exportFocus=1
			case "Enter":
				m.exportFocus=1
			case "Backspace":
				if m.exportCursor>0 && len(m.exportText)>0 {
					r:=[]rune(m.exportText)
					// cursor in runes; simplify delete char before cursor
					if m.exportCursor<=len(r) { r=append(r[:m.exportCursor-1], r[m.exportCursor:]...); m.exportText=string(r); m.exportCursor-- }
				}
			case "Delete":
				r:=[]rune(m.exportText); if m.exportCursor < len(r) { r=append(r[:m.exportCursor], r[m.exportCursor+1:]...); m.exportText=string(r) }
			case "Left":
				if m.exportCursor>0{m.exportCursor--}
			case "Right":
				if m.exportCursor < len([]rune(m.exportText)){m.exportCursor++}
			case "Home":
				m.exportCursor=0
			case "End":
				m.exportCursor=len([]rune(m.exportText))
			default:
				if ev.key=="Space" { app.insertExport(' ') } else if ev.ch!=0 {
					app.insertExport(ev.ch)
				}
			}
		} else {
			switch ev.key {
			case "Escape":
				// In original, Escape with focus on button didn't close easily; but try: focus back to input? Observed staying.
				// We'll keep modal open (do nothing)
			case "Tab":
				m.exportFocus=0
			case "Enter":
				app.doExport()
			default:
				if ev.ch=='q' { /* ignore */ }
				if ev.key=="CtrlC"{app.quit=true}
			}
		}
	case modalError:
		switch ev.key {
		case "Enter", "Escape":
			app.modal=nil
		default:
			if ev.ch=='q' { app.modal=nil }
			if ev.key=="CtrlC"{app.quit=true}
		}
	default:
		if ev.key=="Escape"{app.modal=nil}
	}
}
func (app *uiApp) insertExport(r rune) {
	m:=app.modal; if m==nil{return}
	runes:=[]rune(m.exportText)
	if m.exportCursor<0{m.exportCursor=0}; if m.exportCursor>len(runes){m.exportCursor=len(runes)}
	runes=append(runes[:m.exportCursor], append([]rune{r}, runes[m.exportCursor:]...)...)
	m.exportText=string(runes); m.exportCursor++
}

// drawing modals

func borderChars(kind string) (tl,tr,bl,br,h,v rune) {
	if kind=="double" { return '╔','╗','╚','╝','═','║' }
	return '┌','┐','└','┘','─','│'
}

func (app *uiApp) drawBox(buf *screenBuf, x,y,w,h int, kind string, title string, fill style, borderStyle style) {
	tl,tr,bl,br,hz,vt := borderChars(kind)
	// fill interior
	for yy:=y; yy<y+h; yy++ { for xx:=x; xx<x+w; xx++ { buf.set(xx,yy,' ',fill)}}
	// top/bottom
	for xx:=x; xx<x+w; xx++ { buf.set(xx,y,hz,borderStyle); buf.set(xx,y+h-1,hz,borderStyle)}
	for yy:=y; yy<y+h; yy++ { buf.set(x,yy,vt,borderStyle); buf.set(x+w-1,yy,vt,borderStyle)}
	buf.set(x,y,tl,borderStyle); buf.set(x+w-1,y,tr,borderStyle); buf.set(x,y+h-1,bl,borderStyle); buf.set(x+w-1,y+h-1,br,borderStyle)
	if title!="" {
		tt:= " " + title + " "
		// centered on top border
		tx:= x + (w-len([]rune(tt)))/2
		buf.write(tx,y,tt,borderStyle)
	}
}

func (app *uiApp) drawModal(buf *screenBuf) {
	m:=app.modal; if m==nil{return}
	switch m.kind {
	case modalConfirm:
		app.drawConfirm(buf,m)
	case modalExport:
		app.drawExport(buf,m)
	case modalError:
		app.drawError(buf,m)
	}
}

func (app *uiApp) drawConfirm(buf *screenBuf, m *modalState) {
	// dimensions based on original for 100x30: width 43, height 8 when text wraps to 2 lines, else 7
	textLines := wrapText(m.text, 35) // wrap approx
	h := 6 + len(textLines) // blank, text lines, blank, buttons, blank + borders? Original: top, blank, text(2), blank, buttons, blank, bottom = 2+? count: if text 2 lines: rows: top1 blank1 text2 blank1 buttons1 blank1 bottom1 =8
	if len(textLines)==1 { h=7 } else { h=6+len(textLines) }
	w:=43
	// If text is long single line (empty sub2), w might be? Use 43 for consistency (sub2 example also 43)
	x:=(buf.w-w)/2; if x<0{x=0}
	y:=(buf.h-h)/2; if y<0{y=0}
	borderSt:=style{fg: colorSpec{isDefault:true}, bg: parseColor("#0000ff")} // tview modal border bg blue bright: use palette approx #0000ff gives bg 12 (104?) rgbToPalette for blue 0,0,255 selects 12 => bg 104 correct
	// Modal border style in original: border characters have bg bright blue (104) and fg default
	borderSt = style{fg: colorSpec{isDefault:true}, bg: colorSpec{rgb:[3]int{0,0,255},hasRGB:true}}
	fill:=style{fg: parseColor("#ffffff"), bg: parseColor("#000000")}
	app.drawBox(buf,x,y,w,h,"double","",fill,borderSt)
	// override box interior fill: drawBox filled with fill, border with borderSt - need inner cells bg black: Our drawBox fills whole with fill first then draws border (border overwrites)
	// text centered
	ty:=y+2
	for _, line:= range textLines {
		tx:=x+(w-len([]rune(line)))/2
		buf.write(tx,ty,line,fill)
		ty++
	}
	// buttons row y+h-3
	by:=y+h-3
	// buttons layout: total group text: "no     yes     don't ask me again" with paddings
	// We'll render buttons centered group: builds visible text
	buttons:=[]string{"no","yes","don't ask me again"}
	// compute group width: labels + 2*padding? Visually group: 4 spaces before first etc total inner width 41, group starting at x+5?
	// Simpler: Create line string: "    " + join buttons with 5 spaces + "    " but selected button highlighted including 2 spaces around
	bx:=x+5 // approx: x is border, inside start x+1, then 4 spaces
	// Actually start: inside x+1, then 4 spaces => button "no" at x+1+4
	pos:=x+1+4
	for i, label:= range buttons {
		if i==m.button {
			hl:=style{fg: parseColor("#000000"), bg: parseColor("#ffffff")}
			// two spaces before
			pos = buf.write(pos,by,"  ",hl)
			pos = buf.write(pos,by,label,hl)
			pos = buf.write(pos,by,"  ",hl)
			// then separator spaces (unselected fill)
			// After selected button, there are spaces before next: original has maybe 3 spaces? We'll add 1? To match total, gaps are 5 spaces between labels including highlight padding: if selected has 2 trailing, remaining gap 3? Let's use: gap total 5 spaces between label ends; highlight covers 2 of following? Original selected yes: before yes there is "  " highlight, and after yes "  " highlight then black spaces.
			// Simplify: if not last, add 3 spaces (2 already as highlight trailing? we already added) - We'll add 1 black space to total 5? Let's calculate: label to next label distance should be 5 spaces. We added 2 trailing highlight, need 3 more? But pos after trailing is label+2, next button's leading highlight 2 will be part of gap if next selected... For unselected transitions...
			if i < len(buttons)-1 { pos = buf.write(pos,by,"   ",fill) }
		} else {
			pos = buf.write(pos,by,label,fill)
			if i < len(buttons)-1 {
				// if next is selected, its leading 2 highlight will be part of gap; so add 3 black spaces
				if m.button==i+1 { pos = buf.write(pos,by,"   ",fill) } else { pos = buf.write(pos,by,"     ",fill) }
			}
		}
		_ = bx
	}
}
func wrapText(s string, width int) []string {
	// word wrap like tview: split words, lines <= width (?) But observed wraps at about 35-40.
	// We'll use width 39 if len >?
	// Dynamic: if fits in 41, keep one line? For delete new.txt (40 chars) it wrapped, so limit is maybe 39.
	width=39
	words:=strings.Fields(s)
	var lines []string; cur:=""
	for _, w:= range words {
		if cur=="" { cur=w; continue }
		if len([]rune(cur))+1+len([]rune(w))>width { lines=append(lines,cur); cur=w } else { cur+=" "+w }
	}
	if cur!=""{lines=append(lines,cur)}
	if len(lines)==0{lines=[]string{""}}
	return lines
}

func (app *uiApp) drawExport(buf *screenBuf, m *modalState) {
	w:=50; h:=7
	x:=(buf.w-w)/2; if x<0{x=0}
	y:=(buf.h-h)/2; if y<0{y=0}
	borderSt:=style{fg: colorSpec{isDefault:true}, bg: colorSpec{rgb:[3]int{0,0,255},hasRGB:true}}
	fill:=style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	// original export modal interior default bg
	app.drawBox(buf,x,y,w,h,"double","Export data to JSON",fill,borderSt)
	// border title handling in drawBox centres; original title format with ═ around: "══════ Export data to JSON ════" - our top border will have a title in middle with spaces, border chars will be missing around it but title replaces them - close enough
	// File name label + input
	label:="File name "
	sty:=style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	// Input field background? Original shows export.json in maybe ?? We'll draw label and text
	buf.write(x+2,y+2,label,sty)
	// input text
	inputStyle:=sty
	if m.exportFocus==0 { /* cursor */ }
	buf.write(x+2+len([]rune(label)), y+2, m.exportText, inputStyle)
	// draw cursor block if focused: place a space with reversed? Skip
	// Export button centered row y+4
	btnText:="Export"
	bx:=x+(w-len([]rune(btnText)))/2
	if m.exportFocus==1 {
		hl:=style{fg: parseColor("#000000"), bg: parseColor("#ffffff")}
		buf.write(bx-2,y+4,"  ",hl); buf.write(bx,y+4,btnText,hl); buf.write(bx+len([]rune(btnText)),y+4,"  ",hl)
	} else {
		buf.write(bx,y+4,btnText,sty)
	}
}
func (app *uiApp) drawError(buf *screenBuf, m *modalState) {
	// Error modal width based on text wrapped
	lines:=wrapText(m.errText, 35)
	// width 37 in example for /tmp/viewtest (term 100) maybe dynamic: compute max line length +?
	maxl:=0; for _,l:= range lines { if len([]rune(l))>maxl{maxl=len([]rune(l))}}
	w:=maxl+8; if w<37{w=37}; if w>buf.w-4{w=buf.w-4}
	h:=len(lines)+6 // top, blank?, lines, blank, ok, blank, bottom -> example: lines=3? It had 7 rows (11-17) for error reading file: top, blank, text2, blank, ok, blank, bottom =7 when text 2 lines
	// wrap returns maybe 2 lines for that err
	// adjust: h = 5+len(lines) ? For 2 lines: 7
	h=5+len(lines)
	x:=(buf.w-w)/2; y:=(buf.h-h)/2
	borderSt:=style{fg: colorSpec{isDefault:true}, bg: colorSpec{rgb:[3]int{0,0,255},hasRGB:true}}
	fill:=style{fg: parseColor("#ffffff"), bg: parseColor("#000000")}
	app.drawBox(buf,x,y,w,h,"double","",fill,borderSt)
	ty:=y+2
	for _, line:=range lines { tx:=x+(w-len([]rune(line)))/2; buf.write(tx,ty,line,fill); ty++ }
	// ok button centered at y+h-3
	by:=y+h-3
	hl:=style{fg: parseColor("#000000"), bg: parseColor("#ffffff")}
	// Original ok button is selected by default? Its spaces highlighted?
	bx:=x+(w-2)/2
	buf.write(bx-2,by,"  ",hl); buf.write(bx,by,"ok",hl); buf.write(bx+2,by,"  ",hl)
	_ = fmt.Sprintf
}

func (app *uiApp) drawInfo(buf *screenBuf) {
	it:=app.selectedItem(); if it==nil{return}
	// If selected is parent, info is about parent dir
	var name, path, typ string
	var size, usage int64
	if pi, ok:=it.(*parentItem); ok {
		d:=pi.dir; name=filepathBase(d.GetPath()); path=d.GetPath(); typ="Directory"; size=d.GetSize(); usage=d.GetUsage()
	} else {
		u:=underlyingItem(it); name=u.GetName(); path=u.GetPath(); if u.IsDir(){typ="Directory"} else { // file or other
			// Type File if regular, Other if NotReg
			if f, ok:=u.(*File); ok && f.NotReg { typ="Other" } else { typ="File" }
			if u.IsDir(){typ="Directory"}
		}
		size=u.GetSize(); usage=u.GetUsage()
	}
	w:=80; if w>buf.w {w=buf.w}
	h:=12
	x:=(buf.w-w)/2; y:=(buf.h-h)/2
	borderSt:=style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	fill:=style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	app.drawBox(buf,x,y,w,h,"single","Item info",fill,borderSt)
	// Note drawBox title centred; original info title is centred also
	innerX:=x+2
	buf.write(innerX,y+3,fmt.Sprintf(" Name: %s", name),fill)
	buf.write(innerX,y+4,fmt.Sprintf(" Path: %s", path),fill)
	buf.write(innerX,y+5,fmt.Sprintf(" Type: %s", typ),fill)
	buf.write(innerX,y+7,fmt.Sprintf("    Disk usage: %s (%d B)", formatSize(usage, app.flags), usage),fill)
	buf.write(innerX,y+8,fmt.Sprintf(" Apparent size: %s (%d B)", formatSize(size, app.flags), size),fill)
}

func filepathBase(p string) string {
	if p=="/" {return "/"}
	// trim trailing slash
	p=strings.TrimRight(p,"/")
	idx:=strings.LastIndex(p,"/")
	if idx>=0 { return p[idx+1:] }
	return p
}

func (app *uiApp) drawHelp(buf *screenBuf) {
	lines:=helpLines()
	w:=80; if w>buf.w{w=buf.w}
	// height is lines+2 borders
	h:=len(lines)+2
	if h>buf.h { h=buf.h }
	x:=(buf.w-w)/2; y:=(buf.h-h)/2
	// original help at 100x30 started at y=0 (h=30)
	borderSt:=style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	fill:=style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	app.drawBox(buf,x,y,w,h,"double","gdu help",fill,borderSt)
	for i, line:=range lines {
		if y+1+i >= y+h-1 {break}
		buf.write(x+1,y+1+i,line,fill)
	}
}

func helpLines() []string {
	return []string{
		"",
		"",
		"       up/down, k/j    Move cursor up/down",
		"    pgup/pgdn, g/G     Move cursor top/bottom",
		"   enter, right, l     Go to directory/device",
		"           left, h     Go to parent directory",
		"",
		"                 r     Rescan current directory",
		"                 E     Export analysis data to file as JSON",
		"                 /     Search items by name",
		"                 a     Toggle between showing disk usage and apparent size",
		"                 B     Toggle bar alignment to biggest file or directory",
		"                 c     Show/hide file count",
		"                 m     Show/hide latest mtime",
		"                 b     Spawn shell in current directory",
		"                 q     Quit gdu",
		"                 Q     Quit gdu and print current directory path",
		"",
		"  Item under cursor:",
		"                 d     Delete file or directory",
		"                 e     Empty file or directory",
		"                 space Mark file or directory for deletion",
		"                 I     Ignore file or directory",
		"                 v     Show content of file",
		"                 o     Open file or directory in external program",
		"                 i     Show info about item",
		"",
		"",
	}
}
EOF
"}

