func filepathBase(p string) string {
	if p=="/" {return "/"}
	// trim trailing slash
	p=strings.TrimRight(p,"/")
	idx:=strings.LastIndex(p,"/")
	if idx>=0 { return p[idx+1:] }
	return p
}

