		d:=pi.dir; name=filepathBase(d.GetPath()); path=d.GetPath(); typ="Directory"; size=d.GetSize(); usage=d.GetUsage()
	} else {
		u:=underlyingItem(it); name=u.GetName(); path=u.GetPath()
		if d, ok:=u.(*Dir); ok && d.IsArchive { typ="ZipDirectory" } else if u.IsDir(){ typ="Directory" } else {
			if f, ok:=u.(*File); ok && f.NotReg { typ="Other" } else { typ="File" }
		}
		size=u.GetSize(); usage=u.GetUsage()
		if f, ok:=u.(*File); ok && f.Hlnkc && f.Mli!=0 {
			// collect all files in root with same Mli
			var collect func(d *Dir)
			collect=func(d *Dir){
				for _, ch:=range d.Files {
					if file, ok:=ch.(*File); ok {
						if file.Hlnkc && file.Mli==f.Mli { hardLinks=append(hardLinks, file.GetPath()) }
					} else if sub, ok:=ch.(*Dir); ok { collect(sub) }
				}
			}
			if app.root!=nil { collect(app.root) }
			if len(hardLinks)<=1 { hardLinks=nil }
		}
	}
	extra:=0
	if len(hardLinks)>0 { extra = 1+len(hardLinks)+1 } // header + links + blank separator as per observed height increase (actually 1 header+links+1 blank = +? height)
