package main

import (
	"fmt"
	"os"
	"strings"
	"sync/atomic"
	"time"
)

func (app *uiApp) drawProgress(calculating bool, start time.Time) {
	if app.term==nil {return}
	w,h:=app.term.Size()
	buf:=newBuf(w,h)
	headerSt, _, _, _, _, _, _ := app.styles()
	// header
	if !app.flags.Style.Header.Hidden {
		buf.fillRow(0, headerSt)
		buf.write(0,0," gdu ~ Use arrow keys to navigate, press ? for help ", headerSt)
	}
	// progress box
	bw:=w-2; if bw<10{bw=w}
	bh:=9
	x:=1; y:=(h-bh)/2; if y<2{y=2}
	title:="Scanning..."
	if calculating { title="Calculating..." }
	fill:=style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	borderSt:=fill
	app.drawBox(buf,x,y,bw,bh,"single",title,fill,borderSt)
	items:=atomic.LoadInt64(&app.analyzer.ProgressItems)
	size:=atomic.LoadInt64(&app.analyzer.ProgressSize)
	elapsed:=int(time.Since(start).Seconds())
	current:=app.analyzer.CurrentItem
	maxLen:=app.flags.Style.ProgressModal.CurrentItemNameMaxLen
	if maxLen>0 && len(current)>maxLen {
		// truncate? Original likely truncates in middle? Keep tail?
		current=current[:maxLen]
	}
	line1:=fmt.Sprintf(" Total items: %s, size: %s, elapsed time: %ds", formatComma(items), formatSize(size, app.flags), elapsed)
	line2:=fmt.Sprintf(" Current item: %s", current)
	buf.write(x+1,y+3,line1,fill)
	buf.write(x+1,y+4,line2,fill)
	// render buffer using same serialization as render()
	// Use app.renderBuf
	app.term.w, app.term.h = w,h
	renderBufToStdout(buf)
	_ = strings.Repeat
	_ = os.Stdout
}

func formatComma(n int64) string {
	s:=fmt.Sprintf("%d",n)
	if len(s)<=3{return s}
	var out []string
	for len(s)>3 { out=append([]string{s[len(s)-3:]}, out...); s=s[:len(s)-3] }
	if s!=""{out=append([]string{s},out...)}
	return strings.Join(out,",")
}

func renderBufToStdout(buf *screenBuf) {
	var sb strings.Builder
	sb.WriteString("\x1b[H")
	curStyle := style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	for y:=0;y<buf.h;y++ {
		if y>0 {sb.WriteString("\r\n")}
		for x:=0;x<buf.w;x++ {
			c:=buf.cells[y*buf.w+x]
			if c.sty != curStyle {
				sb.WriteString("\x1b[0m")
				if c.sty.bold || c.sty.fg.set || c.sty.bg.set { sb.WriteString(c.sty.ansiStart()) }
				curStyle=c.sty
			}
			sb.WriteRune(c.ch)
		}
		sb.WriteString("\x1b[0m\x1b[39m\x1b[49m")
		curStyle = style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	}
	os.Stdout.WriteString(sb.String())
}
EOF
# refactor render() to use renderBufToStdout
