	bw:=w-2; if bw<10{bw=w}
	bh:=9
	x:=1; y:=(h-bh)/2; if y<2{y=2}
	title:="Scanning..."
	if calculating { title="Calculating..." }
	fill:=style{fg: colorSpec{isDefault:true}, bg: colorSpec{isDefault:true}}
	borderSt:=fill
	app.drawBox(buf,x,y,bw,bh,"single",title,fill,borderSt)
	items:=atomic.LoadInt64(&app.analyzer.ProgressItems)
	size:=atomic.LoadInt64(&app.analyzer.ProgressSize)
	elapsed:=int(time.Since(start).Seconds())
	current:=app.analyzer.CurrentItem
	maxLen:=app.flags.Style.ProgressModal.CurrentItemNameMaxLen
